    private static IReadOnlyDictionary<EmulationControllerVisualControl, string>?
        VisualCommandIds(ControllerType type) => type is ControllerType.Joypad
            or ControllerType.SegaSg1000Joystick
            or ControllerType.SegaSg1000IiJoypad
            or ControllerType.SegaMasterSystemController
            or ControllerType.SegaControlStick
            or ControllerType.SegaGameGearController
            or ControllerType.SegaMegaDriveThreeButton or ControllerType.SegaMegaDriveSixButton
            or ControllerType.SegaSaturnController or ControllerType.SegaSaturnThreeDControlPad
            or ControllerType.SegaSaturnVirtuaStick
            or ControllerType.SegaDreamcastController
            or ControllerType.SegaArcadePowerStick or ControllerType.SegaArcadePowerStickSixButton
            or ControllerType.SegaDreamcastArcadeStick or ControllerType.SegaDreamcastTwinStick
            or ControllerType.SegaHandleController or ControllerType.SegaSaturnMissionStick
            or ControllerType.SegaSaturnArcadeRacer
        ? BuildVisualCommandIds(type) : null;

    private static IReadOnlyDictionary<EmulationControllerVisualControl, string>
        BuildVisualCommandIds(ControllerType type)
    {
        var commands = new Dictionary<EmulationControllerVisualControl, string>
        {
            [EmulationControllerVisualControl.DirectionUp] = EmulationControllerCommandIds.Up,
            [EmulationControllerVisualControl.DirectionDown] = EmulationControllerCommandIds.Down,
            [EmulationControllerVisualControl.DirectionLeft] = EmulationControllerCommandIds.Left,
            [EmulationControllerVisualControl.DirectionRight] = EmulationControllerCommandIds.Right
        };
        if (type == ControllerType.SegaGameGearController)
        {
            commands[EmulationControllerVisualControl.PrimaryAction] = EmulationControllerCommandIds.B;
            commands[EmulationControllerVisualControl.SecondaryAction] = EmulationControllerCommandIds.A;
            commands[EmulationControllerVisualControl.Start] = EmulationControllerCommandIds.Start;
        }
        else if (type == ControllerType.SegaDreamcastController)
        {
            commands[EmulationControllerVisualControl.FaceA] = EmulationControllerCommandIds.B;
            commands[EmulationControllerVisualControl.FaceB] = EmulationControllerCommandIds.A;
            commands[EmulationControllerVisualControl.FaceX] = EmulationControllerCommandIds.Y;
            commands[EmulationControllerVisualControl.FaceY] = EmulationControllerCommandIds.X;
            commands[EmulationControllerVisualControl.Start] = EmulationControllerCommandIds.Start;
            commands[EmulationControllerVisualControl.LeftTrigger] = EmulationControllerCommandIds.L2;
            commands[EmulationControllerVisualControl.RightTrigger] = EmulationControllerCommandIds.R2;
        }
        else if (type is ControllerType.SegaSaturnController
            or ControllerType.SegaSaturnThreeDControlPad
            or ControllerType.SegaSaturnVirtuaStick)
        {
            commands[EmulationControllerVisualControl.FaceA] = EmulationControllerCommandIds.B;
            commands[EmulationControllerVisualControl.FaceB] = EmulationControllerCommandIds.A;
            commands[EmulationControllerVisualControl.FaceC] = EmulationControllerCommandIds.R;
            commands[EmulationControllerVisualControl.FaceX] = EmulationControllerCommandIds.Y;
            commands[EmulationControllerVisualControl.FaceY] = EmulationControllerCommandIds.X;
            commands[EmulationControllerVisualControl.FaceZ] = EmulationControllerCommandIds.L;
            commands[EmulationControllerVisualControl.Start] = EmulationControllerCommandIds.Start;
            commands[EmulationControllerVisualControl.LeftTrigger] = EmulationControllerCommandIds.L2;
            commands[EmulationControllerVisualControl.RightTrigger] = EmulationControllerCommandIds.R2;
        }
        else if (type is ControllerType.SegaMegaDriveThreeButton
            or ControllerType.SegaMegaDriveSixButton
            or ControllerType.SegaArcadePowerStick
            or ControllerType.SegaArcadePowerStickSixButton)
        {
            commands[EmulationControllerVisualControl.FaceA] = EmulationControllerCommandIds.Y;
            commands[EmulationControllerVisualControl.FaceB] = EmulationControllerCommandIds.B;
            commands[EmulationControllerVisualControl.FaceC] = EmulationControllerCommandIds.A;
            commands[EmulationControllerVisualControl.Start] = EmulationControllerCommandIds.Start;
            if (type is ControllerType.SegaMegaDriveSixButton
                or ControllerType.SegaArcadePowerStickSixButton)
            {
                commands[EmulationControllerVisualControl.FaceX] = EmulationControllerCommandIds.L;
                commands[EmulationControllerVisualControl.FaceY] = EmulationControllerCommandIds.X;
                commands[EmulationControllerVisualControl.FaceZ] = EmulationControllerCommandIds.R;
                commands[EmulationControllerVisualControl.Option] = EmulationControllerCommandIds.Select;
            }
        }
        else
        {
            commands[EmulationControllerVisualControl.PrimaryAction] = EmulationControllerCommandIds.B;
            commands[EmulationControllerVisualControl.SecondaryAction] = EmulationControllerCommandIds.A;
        }
        return commands;
    }

    private static string? NormalizeVisualId(ControllerType type, string? visualId)
    {
        var compatible = CompatibleVisualIds(type);
        return compatible is null ? null : compatible.Contains(visualId ?? string.Empty, StringComparer.Ordinal) ? visualId : DefaultVisualId(type);
    }

    private static string ControllerResourceKey(ControllerType type) => type switch
    {
        ControllerType.Joypad => InputSettingsFunctionsConstants.ResourceControllerJoypad,
        ControllerType.Automatic => InputSettingsFunctionsConstants.ResourceControllerAutomatic,
        ControllerType.None => InputSettingsFunctionsConstants.ResourceControllerNone,
        _ => $"Emulation.Sega.Controller.{type}"
    };

    private static IReadOnlyDictionary<string, string> ToStrings(IReadOnlyDictionary<string, EmulationKey>? values) => values?.ToDictionary(item => item.Key, item => item.Value.ToString(), StringComparer.Ordinal) ?? new Dictionary<string, string>();

    private static IReadOnlyDictionary<string, EmulationKey> ToKeys(IReadOnlyDictionary<string, string> values) => values.Where(item => Enum.TryParse<EmulationKey>(item.Value, true, out _)).ToDictionary(item => item.Key, item => Enum.Parse<EmulationKey>(item.Value, true), StringComparer.Ordinal);
}

namespace GWGUI.Emulation.Sony.Common.Machines.Common.Functions;

internal static partial class InputSettingsFunctions
{
    internal static EmulationInputSettings Describe(MachineConfiguration configuration)
    {
        var model = ModelCatalog.Get(configuration.Model);
        if (!EmulatorCatalog.GetAll(model.Id).Any(adapter => adapter.Id == configuration.EmulatorId))
            return new EmulationInputSettings(null, null, []);
        var input = configuration.Input ?? new InputConfiguration();
        var usbKeyboard = HasUsbKeyboard(configuration);
        var usbMouse = HasUsbMouse(configuration);
        var keyboard = model.HasKeyboard || usbKeyboard ? new EmulationInputBindingSet(usbKeyboard ? UsbKeyboardDefinitions() : [], input.KeyboardBindings ?? ToStrings(input.KeyboardMappings), EmulationInputSource.Keyboard | EmulationInputSource.Mouse | EmulationInputSource.Controller,
            CompatibleVisualIds: usbKeyboard ? [UsbKeyboardVisualId(configuration)] : null, DefaultVisualId: usbKeyboard ? UsbKeyboardVisualId(configuration) : null) : null;
        var mouse = model.MouseButtonCount > 0 || usbMouse ? new EmulationInputBindingSet(usbMouse ? [.. MouseDefinitions(), Definition(nameof(MouseAction.MiddleButton), "Emulation.Mouse.Button.Middle", "Mouse:Middle")] : MouseDefinitions(), MouseValues(input), EmulationInputSource.Mouse | EmulationInputSource.Keyboard | EmulationInputSource.Controller, true) : null;
        if (usbMouse && mouse is not null) mouse = mouse with
        {
            CompatibleVisualIds = [EmulationControllerVisualIds.SonyUsbMouse],
            DefaultVisualId = EmulationControllerVisualIds.SonyUsbMouse,
            VisualCommandIds = UsbMouseVisualCommands()
        };
        var indexes = Enumerable.Range(ControllerPortConstants.MinimumControllerPort, ControllerFunctions.PortCount(configuration));
        if (model.Id == ModelConstants.PlayStation2 && configuration.EmulatorId != "pcee2") indexes = new[] { 8, 9 }.Concat(indexes);
        var ports = indexes.Select(index => DescribePort(configuration, model, index)).ToArray();
        return new EmulationInputSettings(keyboard, mouse, ports);
    }

    internal static MachineConfiguration Apply(MachineConfiguration configuration, EmulationInputSettings settings)
    {
        if (!EmulatorCatalog.GetAll(configuration.Model).Any(adapter => adapter.Id == configuration.EmulatorId))
            return configuration;
        var current = configuration.Input ?? new InputConfiguration();
        var keyboard = settings.Keyboard?.Values ?? current.KeyboardBindings ?? ToStrings(current.KeyboardMappings);
        var mouse = settings.Mouse?.Values.Where(item => !string.IsNullOrWhiteSpace(item.Value) && Enum.TryParse<MouseAction>(item.Key, true, out var action) && action != MouseAction.None)
            .ToDictionary(item => item.Value, item => Enum.Parse<MouseAction>(item.Key, true),
                StringComparer.OrdinalIgnoreCase) ?? current.MouseButtonMappings ?? new Dictionary<string, MouseAction>();
        var controllers = settings.ControllerPorts.Where(port => port.Number <= ControllerFunctions.PortCount(configuration)).Select(port =>
        {
            var index = port.Number - ControllerPortConstants.OneControllerPort;
            if (!Enum.TryParse<ControllerType>(port.SelectedControllerId, true, out var type))
                throw new ArgumentOutOfRangeException(nameof(port.SelectedControllerId), port.SelectedControllerId, null);
            var usb = ControllerCatalog.IsUsbPort(configuration, index);
            if (!ControllerCatalog.Available(configuration, index, usb).Contains(type))
                throw new ArgumentOutOfRangeException(nameof(port.SelectedControllerId), port.SelectedControllerId, null);
            return new ControllerBinding(index, type, port.PhysicalDeviceId,
                port.Bindings.Values.Where(item => !string.IsNullOrWhiteSpace(item.Key) && !string.IsNullOrWhiteSpace(item.Value)).ToDictionary(item => item.Key, item => item.Value, StringComparer.Ordinal),
                port.VisualId, ValidOutputBindings(configuration, type, port.VisualId, port.OutputBindings));
        }).ToArray();
        if (configuration.Model == ModelConstants.PlayStation3)
            controllers = controllers.Concat((current.ControllerBindings ?? [])
                .Where(binding => controllers.All(selected => selected.Port != binding.Port))).ToArray();
        return configuration with
        {
            Input = current with
            {
                KeyboardBindings = keyboard,
                KeyboardMappings = ToKeys(keyboard),
                MouseButtonMappings = mouse,
                ControllerBindings = controllers,
                UsbBindings = configuration.Model == ModelConstants.PlayStation2 && configuration.EmulatorId != "pcee2"
                    ? settings.ControllerPorts.Where(port => port.IsUsb).Select(port =>
                    {
                        if (!Enum.TryParse<ControllerType>(port.SelectedControllerId, out var type)
                            || !ControllerCatalog.Available(configuration, port.Number - 1, true).Contains(type))
                            throw new ArgumentOutOfRangeException(nameof(port.SelectedControllerId));
                        return new ControllerBinding(port.Number - 9, type, port.PhysicalDeviceId,
                            port.Bindings.Values.Where(item => !string.IsNullOrWhiteSpace(item.Key) && !string.IsNullOrWhiteSpace(item.Value))
                                .ToDictionary(item => item.Key, item => item.Value, StringComparer.Ordinal),
                            port.VisualId, ValidOutputBindings(configuration, type, port.VisualId, port.OutputBindings));
                    }).ToArray() : current.UsbBindings
            }
        };
    }

    private static IReadOnlyList<InputBindingDefinition> MouseDefinitions() =>
    [
        Definition(nameof(MouseAction.LeftButton), InputSettingsFunctionsConstants.ResourceMouseButtonLeft, InputSettingsFunctionsConstants.MouseLeft),
        Definition(nameof(MouseAction.RightButton), InputSettingsFunctionsConstants.ResourceMouseButtonRight, InputSettingsFunctionsConstants.MouseRight)
    ];

    private static IReadOnlyDictionary<string, string> MouseValues(InputConfiguration input) => (input.MouseButtonMappings ?? new Dictionary<string, MouseAction>()).Where(item => item.Value != MouseAction.None).ToDictionary(item => item.Value.ToString(), item => item.Key, StringComparer.Ordinal);

    private static IReadOnlyList<InputBindingDefinition> ControllerDefinitions(ControllerType type, Model model) => type is ControllerType.None ? []
        : type == ControllerType.Mouse ? MouseDefinitions()
        : type == ControllerType.Keyboard ? []
        : model.Id == ModelConstants.PocketStation ? Machines.PocketStation.Functions.ControllerFunctions.Definitions
        : model.Id == ModelConstants.Psp ? PspControllerDefinitions()
        : model.Id is ModelConstants.PlayStation or ModelConstants.PlayStation2
            or ModelConstants.PlayStation3
            ? PlayStationControllerDefinitions(type, model) :
        [
            Definition(InputSettingsFunctionsConstants.Up, InputSettingsFunctionsConstants.ResourceControllerActionUp, string.Empty),
            Definition(InputSettingsFunctionsConstants.Down, InputSettingsFunctionsConstants.ResourceControllerActionDown, string.Empty),
            Definition(InputSettingsFunctionsConstants.Left, InputSettingsFunctionsConstants.ResourceControllerActionLeft, string.Empty),
            Definition(InputSettingsFunctionsConstants.Right, InputSettingsFunctionsConstants.ResourceControllerActionRight, string.Empty),
            Definition(InputSettingsFunctionsConstants.B, InputSettingsFunctionsConstants.ResourceControllerActionFire1, string.Empty),
            Definition(InputSettingsFunctionsConstants.A, InputSettingsFunctionsConstants.ResourceControllerActionFire2, string.Empty)
        ];

    private static IReadOnlyList<InputBindingDefinition> ControllerDefinitions(ControllerType type, Model model, MachineConfiguration configuration, int port) =>
        (new Engine().Adapter(configuration) as IEmulatorControllerAdapter)?.GetControllerBindingDefinitions(configuration, type, port) ?? ControllerDefinitions(type, model);

    private static IReadOnlyList<InputBindingDefinition> PspControllerDefinitions() =>
    [
        Definition(InputSettingsFunctionsConstants.Up, InputSettingsFunctionsConstants.ResourceControllerActionUp, string.Empty),
        Definition(InputSettingsFunctionsConstants.Down, InputSettingsFunctionsConstants.ResourceControllerActionDown, string.Empty),
        Definition(InputSettingsFunctionsConstants.Left, InputSettingsFunctionsConstants.ResourceControllerActionLeft, string.Empty),
        Definition(InputSettingsFunctionsConstants.Right, InputSettingsFunctionsConstants.ResourceControllerActionRight, string.Empty),
        Definition(EmulationControllerCommandIds.B, InputSettingsFunctionsConstants.ControllerCross, string.Empty),
        Definition(EmulationControllerCommandIds.A, InputSettingsFunctionsConstants.ControllerCircle, string.Empty),
        Definition(EmulationControllerCommandIds.Y, InputSettingsFunctionsConstants.ControllerSquare, string.Empty),
        Definition(EmulationControllerCommandIds.X, InputSettingsFunctionsConstants.ControllerTriangle, string.Empty),
        Definition(EmulationControllerCommandIds.Select, InputSettingsFunctionsConstants.ControllerSelect, string.Empty),
        Definition(EmulationControllerCommandIds.Start, InputSettingsFunctionsConstants.ControllerStart, string.Empty),
        Definition(EmulationControllerCommandIds.L, EmulationControllerCommandIds.L, string.Empty),
        Definition(EmulationControllerCommandIds.R, EmulationControllerCommandIds.R, string.Empty),
        Definition(InputSettingsFunctionsConstants.PspStickUp, InputSettingsFunctionsConstants.PspStickUpLabel, string.Empty),
        Definition(InputSettingsFunctionsConstants.PspStickDown, InputSettingsFunctionsConstants.PspStickDownLabel, string.Empty),
        Definition(InputSettingsFunctionsConstants.PspStickLeft, InputSettingsFunctionsConstants.PspStickLeftLabel, string.Empty),
        Definition(InputSettingsFunctionsConstants.PspStickRight, InputSettingsFunctionsConstants.PspStickRightLabel, string.Empty)
    ];

    private static IReadOnlyList<InputBindingDefinition> PlayStationControllerDefinitions(ControllerType type, Model model)
    {
        var buttons = PlayStationButtonDefinitions();
        if (type == ControllerType.DanceMat)
            return buttons.Where(definition => definition.Id is EmulationControllerCommandIds.Up or EmulationControllerCommandIds.Down
                or EmulationControllerCommandIds.Left or EmulationControllerCommandIds.Right
                or EmulationControllerCommandIds.Start or EmulationControllerCommandIds.Select
                or EmulationControllerCommandIds.B or EmulationControllerCommandIds.A
                or EmulationControllerCommandIds.Y or EmulationControllerCommandIds.X).ToArray();
        if (type == ControllerType.ArcadeStick)
            return buttons.Where(definition => definition.Id is not (EmulationControllerCommandIds.L3 or EmulationControllerCommandIds.R3)).ToArray();
        if (type is ControllerType.GunCon or ControllerType.Justifier)
            return
            [
                Definition(EmulationControllerCommandIds.B, InputSettingsFunctionsConstants.ResourceControllerActionFire1, string.Empty),
                Definition(EmulationControllerCommandIds.Reload, InputSettingsFunctionsConstants.ResourceControllerActionReload, string.Empty),
                Definition(EmulationControllerCommandIds.A, EmulationControllerCommandIds.A, string.Empty),
                type == ControllerType.Justifier ? Definition(EmulationControllerCommandIds.Start, InputSettingsFunctionsConstants.ControllerStart, string.Empty) : Definition(EmulationControllerCommandIds.X, EmulationControllerCommandIds.B, string.Empty)
            ];
        if (type is ControllerType.NeGcon or ControllerType.NeGconRumble)
            return buttons.Where(definition => definition.Id is
                EmulationControllerCommandIds.Up or EmulationControllerCommandIds.Down
                or EmulationControllerCommandIds.Left or EmulationControllerCommandIds.Right
                or EmulationControllerCommandIds.Start).Concat(
                new InputBindingDefinition[]
                {
                    Definition(EmulationControllerCommandIds.A, EmulationControllerCommandIds.A, string.Empty),
                    Definition(EmulationControllerCommandIds.X, EmulationControllerCommandIds.B, string.Empty),
                    Definition(EmulationControllerCommandIds.R, EmulationControllerCommandIds.R, string.Empty),
                    Definition(EmulationControllerCommandIds.R2, InputSettingsFunctionsConstants.NeGconButtonI, string.Empty),
                    Definition(EmulationControllerCommandIds.L2, InputSettingsFunctionsConstants.NeGconButtonII, string.Empty),
                    Definition(EmulationControllerCommandIds.L, EmulationControllerCommandIds.L, string.Empty),
                    Definition(InputSettingsFunctionsConstants.LeftStickLeft, InputSettingsFunctionsConstants.ResourceSteeringLeft, string.Empty),
                    Definition(InputSettingsFunctionsConstants.LeftStickRight, InputSettingsFunctionsConstants.ResourceSteeringRight, string.Empty)
                }).ToArray();
        if (model.Id == ModelConstants.PlayStation && type == ControllerType.Joystick)
            return buttons.Where(definition => definition.Id is not (EmulationControllerCommandIds.L3 or EmulationControllerCommandIds.R3)).ToArray();
        if (type is ControllerType.AnalogController or ControllerType.AnalogJoystick)
            buttons = buttons.Where(definition => definition.Id is not (EmulationControllerCommandIds.L3 or EmulationControllerCommandIds.R3)).ToArray();
        var analogButtons = model.Id == ModelConstants.PlayStation && type is ControllerType.DualShock or ControllerType.AnalogController or ControllerType.AnalogJoystick ? new[] { Definition(InputSettingsFunctionsConstants.Analog, InputSettingsFunctionsConstants.Analog, string.Empty) } : [];
        return buttons.Concat(analogButtons).Concat(AnalogStickDefinitions()).ToArray();
    }

