            {
                try
                {
                    EmulationChildProcessLifetime.WaitForExit(process, graceful: true, ProcessCoreConstants.GracefulShutdownTimeoutMilliseconds);
                }
                finally { DisposeSafely(process); }
            }
            while (_audio.TryDequeue(out _)) { }
