namespace GWGUI.Emulation.Thomson.Emulators.Theodore.Interop.Services;
internal sealed class ExternalCore : IEmulatorCore, IEmulationCoreCallbacks
{
    ExternalCoreApi.EnvironmentCallback IEmulationCoreCallbacks.Environment => _environment!.Callback;
    ExternalCoreApi.VideoCallback IEmulationCoreCallbacks.Video => _video!.Callback;
    ExternalCoreApi.AudioSampleCallback IEmulationCoreCallbacks.AudioSample => _audio!.SampleCallback;
    ExternalCoreApi.AudioBatchCallback IEmulationCoreCallbacks.AudioBatch => _audio!.BatchCallback;
    ExternalCoreApi.InputPollCallback IEmulationCoreCallbacks.InputPoll => _input!.PollCallback;
    ExternalCoreApi.InputStateCallback IEmulationCoreCallbacks.InputState => _input!.StateCallback;

    private readonly string _path;
    private readonly ExternalCoreInfo _info;
    private ExternalCoreLibrary? _library;
    private ExternalCoreExports? _exports;
    private VideoCallbackHost? _video;
    private AudioCallbackHost? _audio;
    private EnvironmentCallbackHost? _environment;
    private InputCallbackHost? _input;
    private LoadedContent? _content;
    private bool _initialized, _loaded, _disposed;
    private IReadOnlyList<string> _lastDiagnostics = [];
    internal ExternalCore(string path)
    {
        _path = Path.GetFullPath(path);
        _info = CoreProbeFunctions.Inspect(_path);
        using var stream = File.OpenRead(_path);
        CoreSha256 = Convert.ToHexString(SHA256.HashData(stream));
    }

    public Emulator Emulator => Emulator.Theodore;
    public VideoFrame? LatestVideoFrame => _video?.LatestFrame;
    public AudioChunk? LatestAudioChunk => _audio?.LatestChunk;
    public IReadOnlyList<CoreOption> Options => _environment?.Options ?? [];
    public IReadOnlyList<string> Diagnostics => _environment?.Diagnostics ?? _lastDiagnostics;
    public IReadOnlyDictionary<int, bool> LedStates { get; } = new Dictionary<int, bool>();
    public string CoreName => _info.LibraryName;
    public string CoreVersion => _info.LibraryVersion;
    public string CoreSha256 { get; }
    public IReadOnlySet<string> SupportedContentExtensions => _info.Extensions;
    public bool SupportsSaveStates => _loaded && _exports is { } exports && exports.GetSerializedSize()is var size && size > 0 && size <= (nuint)Array.MaxLength;
    public double FramesPerSecond => _environment?.FramesPerSecond ?? 0;
    public int SampleRate => _audio?.SampleRate ?? 0;
    public EmulationVideoStandard? Region { get; private set; }
    public int BufferedAudioFrames => _audio?.BufferedFrames ?? 0;
    public long AudioOverrunCount => _audio?.OverrunCount ?? 0;
    public long AudioUnderrunCount => _audio?.UnderrunCount ?? 0;
    public HostProcessState HostProcessState => HostProcessState.InProcess;
    public int? HostProcessId => null;

    public bool TryDequeueAudio(out AudioChunk? chunk)
    {
        chunk = null;
        return _audio?.TryDequeue(out chunk) == true;
    }

    public void Initialize(MachineConfiguration configuration, string sessionDirectory, string? saveDirectory = null)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (_library is not null)
            throw new InvalidOperationException();
        ConfigurationFunctions.Validate(configuration);
        if (configuration.Core != Emulator)
            throw new ArgumentException(nameof(configuration));
        var completed = false;
        try
        {
            _library = new ExternalCoreLibrary(_path);
            _exports = CoreFunctions.ResolveExports(_library);
            _video = new VideoCallbackHost();
            _audio = new AudioCallbackHost();
            _environment = new EnvironmentCallbackHost(
                _video,
                _audio,
                NativeOptions.Prepare(configuration),
                Path.Combine(sessionDirectory, "System"),
                Path.Combine(sessionDirectory, "Content"),
                saveDirectory ?? Path.Combine(sessionDirectory, "Saves"),
                Path.Combine(sessionDirectory, "Assets")
            );
            _input = new InputCallbackHost(configuration, _environment, _video);
            ExternalCoreEnvironmentFunctions.InstallCallbacks(_exports, this);
            _exports.Initialize();
            _initialized = true;
            for (var port = ControllerConstants.FirstPort; port < ControllerConstants.PortCount; port++)
                _exports.SetControllerPortDevice((uint)port, 1);
            var paths = NativeMedia.InitialContentPaths(configuration);
            if (paths.Count > 1)
                throw MediaUnsupported();
            if (paths.Count == 1)
            {
                var path = paths[0];
                _ = NativeMedia.Category(path);
                if (!_info.Extensions.Contains(Path.GetExtension(path).TrimStart('.')))
                    throw MediaUnsupported();
                var media = configuration.Media.FirstOrDefault(item => string.Equals(Path.GetFullPath(item.Path), path, StringComparison.OrdinalIgnoreCase));
                _content = new LoadedContent(path, sessionDirectory, media?.IsReadOnly ?? true);
            }
            else if (!_environment.SupportsNoGame)
                throw MediaUnsupported();
            if (!_exports.LoadGame(_content?.GameInfo ?? nint.Zero))
                throw MediaUnsupported();
            _loaded = true;
            _content?.MarkLoaded();
            _exports.GetSystemAvInfo(out var info);
            _environment.ApplyAvInfo(info);
            Region = _exports.GetRegion() == 1 ? EmulationVideoStandard.Pal : EmulationVideoStandard.Ntsc;
            ThrowCallbackFailure();
            completed = true;
        }
        finally
        {
            if (!completed)
                Cleanup();
        }
    }

    public void RunFrame()
    {
        RequireExports().Run();
        ThrowCallbackFailure();
    }

    public void HardReset()
    {
        _input?.Release();
        RequireExports().Reset();
    }

    public void SetInput(EmulationInputSnapshot snapshot) => (_input ?? throw new InvalidOperationException()).Update(snapshot);
    public void SetOption(string key, string value) => (_environment ?? throw new InvalidOperationException()).SetOption(key, value);
    public void SetControllerPortDevice(int port, PeripheralCategory peripheral)
    {
        if (port < 0 || port >= ControllerConstants.PortCount || !Enum.IsDefined(peripheral))
            throw new ArgumentException(nameof(port));
        RequireExports().SetControllerPortDevice((uint)port, peripheral == PeripheralCategory.None ? 0u : 1u);
    }

    public void InsertMedia(MediaConfiguration media) => throw MediaUnsupported();
    public void EjectMedia(EmulationMediaSlot slot) => throw MediaUnsupported();
    public void SelectDisk(int index)
    {
        if (index != 0)
            throw new ArgumentOutOfRangeException(nameof(index));
    }

    public DiskStatus GetDiskStatus() => new(_content is null ? 0 : 1, 0, _content is null, []);
    public byte[] SaveState()
    {
        var exports = RequireExports();
        var size = exports.GetSerializedSize();
        if (size == 0 || size > (nuint)Array.MaxLength)
            throw StateInvalid();
        var pointer = Marshal.AllocHGlobal(checked((int)size));
        try
        {
            if (!exports.Serialize(pointer, size))
                throw StateInvalid();
            var result = GC.AllocateUninitializedArray<byte>((int)size);
            Marshal.Copy(pointer, result, 0, result.Length);
            return result;
        }
        finally
        {
            Marshal.FreeHGlobal(pointer);
        }
    }

    public void LoadState(ReadOnlySpan<byte> state)
    {
        if (state.IsEmpty)
            throw StateInvalid();
        var pointer = Marshal.AllocHGlobal(state.Length);
        try
        {
            var bytes = state.ToArray();
            Marshal.Copy(bytes, 0, pointer, bytes.Length);
            if (!RequireExports().Unserialize(pointer, (nuint)bytes.Length))
                throw StateInvalid();
        }
        finally
        {
            Marshal.FreeHGlobal(pointer);
        }
    }

    public void Stop() => Cleanup();
    public void Dispose()
    {
        if (_disposed)
            return;
        try
        {
            Cleanup();
        }
        finally
        {
            _disposed = true;
        }
    }

    private ExternalCoreExports RequireExports() => _loaded && _exports is { } exports ? exports : throw new InvalidOperationException();
    private void ThrowCallbackFailure()
    {
        var error = _environment?.Failure ?? _video?.Failure ?? _audio?.Failure ?? _input?.Failure;
        if (error is not null)
            throw error;
    }

    private void Cleanup()
    {
        var exports = _exports;
        var library = _library;
        var environment = _environment;
        var input = _input;
        var video = _video;
        var audio = _audio;
        var content = _content;
        var loaded = _loaded;
        var initialized = _initialized;
        _lastDiagnostics = environment?.Diagnostics.ToArray() ?? _lastDiagnostics;
        _exports = null;
        _library = null;
        _environment = null;
        _input = null;
        _video = null;
        _audio = null;
        _content = null;
        _loaded = false;
        _initialized = false;
        try
        {
            try { input?.Release(); }
            finally { CoreLifecycleFunctions.Cleanup(exports, loaded, initialized, () => environment?.Dispose(), () => library?.Dispose()); }
        }
        finally
        {
            GC.KeepAlive(environment);
            GC.KeepAlive(input);
            GC.KeepAlive(video);
            GC.KeepAlive(audio);
            try { content?.Dispose(); }
            finally
            {
                try { video?.Dispose(); }
                finally { audio?.Dispose(); }
            }
        }
    }
    private static EmulationMessageException MediaUnsupported() => new(new EmulationMessage(EmulationMessageCategory.Media, EmulationMessageCode.MediaUnsupported, EmulationMessageSeverity.Error, EmulationMessageTarget.Dialog));
    private static EmulationMessageException StateInvalid() => new(new EmulationMessage(EmulationMessageCategory.SavedState, EmulationMessageCode.SavedStateInvalid, EmulationMessageSeverity.Error, EmulationMessageTarget.Dialog));
}

using GWGUI.Emulation.Interop;

namespace GWGUI.Emulation.Thomson.Emulators.Theodore.Interop.Services;

internal sealed class InputCallbackHost
{
    private const uint JoypadDevice = 1;
    private const uint PointerDevice = 6;
    private const uint DeviceMask = 255;
    private const uint FireButton = 0;
    private const uint UpButton = 4;
    private const uint DownButton = 5;
    private const uint LeftButton = 6;
    private const uint RightButton = 7;
    private const uint PointerHorizontal = 0;
    private const uint PointerVertical = 1;
    private const uint PointerPressed = 2;
    private const float PointerRange = ushort.MaxValue;
    private const int PointerMinimum = -short.MaxValue;
    private const int PointerMaximum = short.MaxValue;
    private readonly EnvironmentCallbackHost _environment;
    private readonly VideoCallbackHost _video;
    private readonly KeyboardState _keyboard;
    private readonly bool _lightPenEnabled;
    private EmulationInputSnapshot _input = EmulationInputSnapshot.Empty;
    private int _x, _y;
    internal InputCallbackHost(MachineConfiguration configuration, EnvironmentCallbackHost environment, VideoCallbackHost video)
    {
        _environment = environment;
        _video = video;
        _keyboard = new KeyboardState(configuration.Model);
        _lightPenEnabled = configuration.Options.GetValueOrDefault(SettingsConstants.LightPenEnabled, EmulationSettingConstants.Enabled) == EmulationSettingConstants.Enabled;
        PollCallback = OnPoll;
        StateCallback = OnState;
    }
    internal ExternalCoreApi.InputPollCallback PollCallback { get; }
    internal ExternalCoreApi.InputStateCallback StateCallback { get; }
    internal Exception? Failure { get; private set; }
    internal void Update(EmulationInputSnapshot input) => _input = input;

    private void OnPoll()
    {
        try
        {
            _keyboard.Publish(_input.Keys, _environment.Keyboard);
            if (_lightPenEnabled && _video.LatestFrame is { } frame)
            {
                _x = (int)Math.Clamp(_x + Math.Round((double)_input.Pointer.DeltaX * PointerRange / frame.Width), PointerMinimum, PointerMaximum);
                _y = (int)Math.Clamp(_y + Math.Round((double)_input.Pointer.DeltaY * PointerRange / frame.Height), PointerMinimum, PointerMaximum);
            }
            _input = _input with { Pointer = _input.Pointer with { DeltaX = 0, DeltaY = 0 } };
        }
        catch (Exception error) { Failure ??= error; }
    }

    private short OnState(uint port, uint device, uint index, uint id)
    {
        device &= DeviceMask;
        if (device == PointerDevice && port == ControllerConstants.PortCount)
            return id switch
            {
                PointerHorizontal => (short)_x,
                PointerVertical => (short)_y,
                PointerPressed => _lightPenEnabled && _input.Pointer.Left ? (short)1 : (short)0,
                _ => 0
            };
        if (device != JoypadDevice || port >= _input.Controllers.Count) return 0;
        var controller = _input.Controllers[(int)port];
        var pressed = id switch { FireButton => (controller.Buttons & ControllerConstants.FireButtonMask) != 0, UpButton => controller.LeftY < 0, DownButton => controller.LeftY > 0, LeftButton => controller.LeftX < 0, RightButton => controller.LeftX > 0, _ => false };
        return pressed ? (short)1 : (short)0;
    }

    internal void Release()
    {
        _keyboard.Release(_environment.Keyboard);
        _input = EmulationInputSnapshot.Empty;
        Failure = null;
    }
}

