        try { _audioOutput.Flush(); }
        catch { _audioOutput.Dispose(); _audioOutput = null; }
    }

    private void WriteAudio(ReadOnlySpan<short> samples)
    {
        if (_audioOutput is null) return;
        if (_audioVolume >= 1f)
        {
