        });

    private static T WithFileLock<T>(string path, Func<T> action)
    {
        using var mutex = CreateMutex(path);
        var lockTaken = Wait(mutex);
        try { return action(); }
        finally { if (lockTaken) mutex.ReleaseMutex(); }
    }

