using System.IO;
using System.Text.Json;
using GWGUI.Emulation.Functions;

namespace GWGUI.Tests.Emulation;

public sealed class NativeConfigurationLoadFileAuditTests
{
    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web);

    [Fact]
    public async Task CallerControlsEnumerationOrderAndSeesCreatedDirectory()
    {
        using var fixture = new Fixture();
        var first = fixture.Write("a.json", "alpha");
        var second = fixture.Write("b.json", "beta");
        var malformed = fixture.WriteRaw("broken.json", "{");
        var directory = Path.Combine(fixture.Root, "created");
        var task = ConfigurationFileAccessFunctions.ReadDocumentsAsync(directory,
            () =>
            {
                Assert.True(Directory.Exists(directory));
                return new[] { second, malformed, Path.Combine(fixture.Root, "missing.json"), first };
            },
            element => element.Deserialize<Document>(Options)!,
            static document => document.Name, CancellationToken.None);
        Assert.True(task.IsCompletedSuccessfully);
        Assert.Equal(["beta", "alpha"], await task);
    }

    [Fact]
    public void CancellationWithAFileEscapesSynchronouslyBeforeParsing()
    {
        using var fixture = new Fixture();
        var file = fixture.Write("a.json", "value");
        using var stop = new CancellationTokenSource();
        stop.Cancel();
        Assert.Throws<OperationCanceledException>((Action)(() =>
        {
            _ = ConfigurationFileAccessFunctions.ReadDocumentsAsync<Document, string>(fixture.Root, () => [file],
                _ => throw new InvalidOperationException(), _ => throw new InvalidOperationException(), stop.Token);
        }));
    }

    [Fact]
    public async Task EmptyEnumerationRetainsPrecancelledSuccess()
    {
        using var fixture = new Fixture();
        using var stop = new CancellationTokenSource();
        stop.Cancel();
        var result = await ConfigurationFileAccessFunctions.ReadDocumentsAsync<Document, string>(fixture.Root,
            static () => Array.Empty<string>(), _ => throw new InvalidOperationException(),
            _ => throw new InvalidOperationException(), stop.Token);
        Assert.Empty(result);
    }

    [Theory]
    [InlineData("deserialize", "json")]
    [InlineData("deserialize", "io")]
    [InlineData("deserialize", "data")]
    [InlineData("deserialize", "argument")]
    [InlineData("restore", "json")]
    [InlineData("restore", "io")]
    [InlineData("restore", "data")]
    [InlineData("restore", "argument")]
    public async Task FourNativeErrorsSkipOneFileAndDisposeItsDocument(string stage, string kind)
    {
        using var fixture = new Fixture();
        var first = fixture.Write("a.json", "bad");
        var second = fixture.Write("b.json", "good");
        var borrowed = new List<JsonElement>();
        void Fail(string current, Document document)
        {
            if (current == stage && document.Name == "bad") throw Failure(kind);
        }
        var result = await ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Root, () => new[] { first, second },
            element =>
            {
                if (borrowed.Count > 0) AssertDisposed(borrowed[^1]);
                borrowed.Add(element);
                var document = element.Deserialize<Document>(Options)!;
                Fail("deserialize", document);
                return document;
            },
            document => { Assert.Equal(document.Name, borrowed[^1].GetProperty("name").GetString()); Fail("restore", document); return document.Name; },
            CancellationToken.None);
        Assert.Equal("good", Assert.Single(result));
        Assert.Equal(2, borrowed.Count);
        foreach (var element in borrowed) AssertDisposed(element);
    }

    [Theory]
    [InlineData("deserialize")]
    [InlineData("restore")]
    public void OtherErrorsEscapeSynchronouslyAndStillDisposeTheDocument(string stage)
    {
        using var fixture = new Fixture();
        var file = fixture.Write("a.json", "value");
        var failure = new InvalidOperationException("Injected");
        JsonElement borrowed = default;
        Assert.Same(failure, Record.Exception((Action)(() =>
        {
            _ = ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Root, () => new[] { file },
                element =>
                {
                    borrowed = element;
                    if (stage == "deserialize") throw failure;
                    return element.Deserialize<Document>(Options)!;
                },
                document => { if (stage == "restore") throw failure; return document.Name; },
                CancellationToken.None);
        })));
        AssertDisposed(borrowed);
    }

    [Theory]
    [InlineData("json")]
    [InlineData("io")]
    [InlineData("data")]
    [InlineData("argument")]
    public void EnumerationErrorsStayOutsideThePerFileCatch(string kind)
    {
        using var fixture = new Fixture();
        var failure = Failure(kind);
        Assert.Same(failure, Record.Exception((Action)(() =>
        {
            _ = ConfigurationFileAccessFunctions.ReadDocumentsAsync<Document, string>(fixture.Root,
                () => throw failure, _ => throw new InvalidOperationException(),
                _ => throw new InvalidOperationException(), CancellationToken.None);
        })));
    }

    [Fact]
    public async Task JsonElementIsBorrowedThroughRestorationAndReleasedBeforeReturn()
    {
        using var fixture = new Fixture();
        var file = fixture.Write("a.json", "value");
        JsonElement borrowed = default;
        var result = await ConfigurationFileAccessFunctions.ReadDocumentsAsync(fixture.Root, () => new[] { file },
            element => { borrowed = element; return element.Deserialize<Document>(Options)!; },
            document =>
            {
                Assert.Equal(document.Name, borrowed.GetProperty("name").GetString());
                return document.Name;
            }, CancellationToken.None);
        Assert.Equal("value", Assert.Single(result));
        AssertDisposed(borrowed);
    }

    private static void AssertDisposed(JsonElement element)
        => Assert.Throws<ObjectDisposedException>((Action)(() => { _ = element.GetProperty("name"); }));

    private static Exception Failure(string kind) => kind switch
    {
        "json" => new JsonException("Injected"),
        "io" => new IOException("Injected"),
