using System.IO;
using System.Reflection;

namespace GWGUI.Tests.Emulation;

public sealed class ConfigurationDeletionFileAuditTests
{
    public static IEnumerable<object[]> Stores()
    {
        foreach (var value in NativeConfigurationSaveGateTests.Stores())
            yield return [value[0], true];
        foreach (var value in LegacyConfigurationPathTests.Stores())
            yield return [value[0], false];
    }

    [Theory]
    [MemberData(nameof(Stores))]
    public void DeletesOnlyOwnedConfigurationDirectory(Type type, bool nativeGuard)
    {
        var workspace = Path.GetFullPath(@"F:\GW GUI");
        var root = Path.GetFullPath(Path.Combine(workspace, ".configuration-delete-audit-" + Guid.NewGuid().ToString("N")));
        Assert.Equal(workspace, Path.GetDirectoryName(root));
        try
        {
            Directory.CreateDirectory(root);
            var store = Activator.CreateInstance(type, [root, null])!;
            var delete = type.GetMethod("Delete")!;
            var id = Guid.NewGuid();
            var target = Path.Combine(root, id.ToString("N"));
            var neighbor = Path.Combine(root, Guid.NewGuid().ToString("N"));
            var legacy = Path.Combine(root, id.ToString("N") + ".json");
            Directory.CreateDirectory(Path.Combine(target, "nested"));
            File.WriteAllText(Path.Combine(target, "nested", "owned.txt"), "owned");
            Directory.CreateDirectory(neighbor);
            File.WriteAllText(Path.Combine(neighbor, "keep.txt"), "neighbor");
            File.WriteAllText(legacy, "root migration file must remain untouched");

            delete.Invoke(store, [id]);
            Assert.False(Directory.Exists(target));
            Assert.Equal("neighbor", File.ReadAllText(Path.Combine(neighbor, "keep.txt")));
            Assert.True(File.Exists(legacy));
            delete.Invoke(store, [id]);

            File.WriteAllText(target, "same-name file");
            delete.Invoke(store, [id]);
            Assert.Equal("same-name file", File.ReadAllText(target));

            var emptyIdDirectory = Path.Combine(root, Guid.Empty.ToString("N"));
            Directory.CreateDirectory(emptyIdDirectory);
            if (nativeGuard)
            {
                var error = Assert.Throws<TargetInvocationException>(() => delete.Invoke(store, [Guid.Empty]));
                Assert.Equal("id", Assert.IsType<ArgumentException>(error.InnerException).Message);
                Assert.True(Directory.Exists(emptyIdDirectory));
            }
            else
            {
                delete.Invoke(store, [Guid.Empty]);
                Assert.False(Directory.Exists(emptyIdDirectory));
            }
        }
        finally
        {
            var resolved = Path.GetFullPath(root);
            if (!string.Equals(Path.GetDirectoryName(resolved), workspace, StringComparison.OrdinalIgnoreCase)
                || !Path.GetFileName(resolved).StartsWith(".configuration-delete-audit-", StringComparison.Ordinal))
                throw new InvalidOperationException("Fixture cleanup target outside expected workspace.");
            if (Directory.Exists(resolved)) Directory.Delete(resolved, recursive: true);
        }
    }
}

