using System.IO;
using System.IO.MemoryMappedFiles;
using System.Runtime.Versioning;
using GWGUI.Emulation.Constants;
using GWGUI.Emulation.Functions;

namespace GWGUI.Tests.Emulation;

[SupportedOSPlatform("windows")]
public sealed class FixedVideoMapOwnershipAuditTests
{
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void OwnedHandlesCloseAndIndependentOwnerRemainsUsable(bool fail)
    {
        var name = "GWGUI.Audit.FixedVideo." + Guid.NewGuid().ToString("N");
        MemoryMappedFile? owner = null;
        MemoryMappedViewAccessor? borrowedView = null;
        var expected = new InvalidOperationException("callback failure");
        try
        {
            owner = MemoryMappedFile.CreateNew(name, EmulationHostProtocolConstants.VideoMapCapacity);
            void Run() => EmulationHostProtocolFunctions.WithSharedVideoMap(name, 0, view =>
            {
                borrowedView = view;
                view.Write(0, (byte)41);
                if (fail) throw expected;
            });
            if (fail) Assert.Same(expected, Assert.Throws<InvalidOperationException>(Run));
            else Run();

            Assert.NotNull(borrowedView);
            Assert.Throws<ObjectDisposedException>(() => borrowedView.ReadByte(0));
            using var observation = owner.CreateViewAccessor(0, 1, MemoryMappedFileAccess.Read);
            Assert.Equal((byte)41, observation.ReadByte(0));
        }
        finally
        {
            owner?.Dispose();
        }
        AssertMissing(name);
    }

    [Fact]
    public void FailedViewCreationReleasesTheOpenedMap()
    {
        var name = "GWGUI.Audit.FixedVideo." + Guid.NewGuid().ToString("N");
        MemoryMappedFile? owner = null;
        var called = false;
        try
        {
            owner = MemoryMappedFile.CreateNew(name, EmulationHostProtocolConstants.VideoMapCapacity);
            Assert.Throws<ArgumentOutOfRangeException>(() =>
                EmulationHostProtocolFunctions.WithSharedVideoMap(name, -1, _ => called = true));
            Assert.False(called);
        }
        finally
        {
            owner?.Dispose();
        }
        AssertMissing(name);
    }

    [Fact]
    public void MissingMapDoesNotInvokeTheBorrower()
    {
        var name = "GWGUI.Audit.FixedVideo." + Guid.NewGuid().ToString("N");
        var called = false;
        Assert.Throws<FileNotFoundException>(() =>
            EmulationHostProtocolFunctions.WithSharedVideoMap(name, 0, _ => called = true));
        Assert.False(called);
        AssertMissing(name);
    }

    private static void AssertMissing(string name)
    {
        Assert.Throws<FileNotFoundException>(() =>
        {
            using var remaining = MemoryMappedFile.OpenExisting(name);
        });
    }
}

