    private static void WriteSuccess(BinaryWriter writer) => writer.Write(true);

    [DllImport(CoreHostConstants.KernelLibrary)]
    private static extern uint GetErrorMode();

    [DllImport(CoreHostConstants.KernelLibrary)]
    private static extern uint SetErrorMode(uint mode);
