using System.Runtime.InteropServices;
using System.Runtime.Versioning;
using GWGUI.Emulation.Functions;

namespace GWGUI.Tests.Emulation;

[SupportedOSPlatform("windows")]
public sealed class WindowsErrorModeAuditTests
{
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void OriginalModeIsRestoredAfterSuccessOrFailure(bool fail)
    {
        var initial = GetErrorMode();
        var invoked = false;
        var failure = new InvalidOperationException("session failure");
        try
        {
            SetErrorMode(initial | 0x8000);
            var baseline = GetErrorMode();
            Action session = () =>
            {
                invoked = true;
                Assert.Equal(baseline | 0x0001u | 0x0002u, GetErrorMode());
                if (fail) throw failure;
            };
            if (fail)
                Assert.Same(failure, Assert.Throws<InvalidOperationException>(
                    () => EmulationHostProtocolFunctions.WithSuppressedErrorDialogs(session)));
            else
                EmulationHostProtocolFunctions.WithSuppressedErrorDialogs(session);
            Assert.True(invoked);
            Assert.Equal(baseline, GetErrorMode());
        }
        finally { SetErrorMode(initial); }
        Assert.Equal(initial, GetErrorMode());
    }

    [DllImport("kernel32.dll")]
    private static extern uint GetErrorMode();

    [DllImport("kernel32.dll")]
    private static extern uint SetErrorMode(uint mode);
}

