                case ExternalCoreApiConstants.GetDiskControlVersion:
                    _ = ExternalCoreEnvironmentFunctions.WriteInteger(data, DiskControlVersion);
                    return true;
                case ExternalCoreApiConstants.SetInputDescriptors:
