namespace GWGUI.Emulation.Sony.Emulators.Common.Interop.Services;

internal sealed partial class ExternalHostCallbacks : IEmulationCoreEnvironmentCommands
{
    private bool HandleEnvironment(uint command, nint data)
    {
        try
        {
            if (ExternalCoreEnvironmentFunctions.TryHandleLegacyQuery(command, data,
                    2, ExternalCoreInteropConstants.MessageInterfaceVersion, out var legacyQueryResult))
                return legacyQueryResult;
            if (ExternalCoreEnvironmentFunctions.TryHandleLegacyEnvironmentCommand(command, data,
                    this, true, out var legacyEnvironmentResult))
                return legacyEnvironmentResult;
            switch (command)
            {
                case MultichannelAudioConstants.GetBatchCallback:
                    if (data == nint.Zero) return false;
                    Marshal.StructureToPtr(new MultichannelAudioApi.Callback
                    {
                        Int16 = Marshal.GetFunctionPointerForDelegate(MultichannelAudioBatch),
                        Float = nint.Zero
                    }, data, false);
                    return true;
                case ExternalCoreApiConstants.GetRumbleInterface:
                    return ((IEmulationCoreEnvironmentCommands)this).SetRumbleInterface(data);
                case ExternalCoreApiConstants.Shutdown:
                    _shutdownRequested = true;
                    return true;
                case ExternalCoreApiConstants.SetHardwareRender:
                    return HardwareRender.Configure(data);
                case ExternalCoreApiConstants.GetPreferredHardwareRender:
                    return ExternalCoreEnvironmentFunctions.WriteInteger(data, OpenGlHardwareRenderContext.OpenGlCoreContextType);
                case ExternalCoreApiConstants.SetCoreOptionsV2:
                    RegisterVersionTwoOptions(data);
                    return true;
                case ExternalCoreApiConstants.SetCoreOptionsV2International:
                    RegisterVersionTwoOptions(Marshal.ReadIntPtr(data));
                    return true;
                case ExternalCoreApiConstants.SetVariables:
                    RegisterLegacyOptions(data);
                    return true;
                case ExternalCoreApiConstants.GetVariable:
                    return ReturnOption(data);
                case ExternalCoreApiConstants.GetVariableUpdate:
                    _ = EmulationCoreOptionFunctions.GetAndClearUpdated(data, ref _optionsUpdated);
                    return true;
                case ExternalCoreApiConstants.SetCoreOptionsDisplay:
                    return ApplyOptionVisibility(data);
                case ExternalCoreApiConstants.SetCoreOptionsUpdateDisplayCallback:
                    return CaptureOptionsDisplayCallback(data);
                case ExternalCoreApiConstants.SetFastForwardingOverride:
                    return false;
                default:
                    if (_unknownEnvironmentCommands.Add(command)) AddDiagnostic($"Unsupported environment command: {command}");
                    return false;
            }
        }
        catch
        {
            return false;
        }
    }

    bool IEmulationCoreEnvironmentCommands.SetRotation(nint data) => false;

    bool IEmulationCoreEnvironmentCommands.CapturePerformanceLevel(nint data) => false;

    bool IEmulationCoreEnvironmentCommands.SetPixelFormat(nint data)
    {
        _pixelFormat = ExternalCoreEnvironmentFunctions.ReadLegacyPixelFormat(data,
            static value => new NotSupportedException(CoreExceptions.UnsupportedPixelFormat(value)));
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.SetSystemAvInfo(nint data)
    {
        return ApplySystemAvInfo(data);
    }

    bool IEmulationCoreEnvironmentCommands.SetGeometry(nint data)
    {
        return ApplyGeometry(data);
    }

    bool IEmulationCoreEnvironmentCommands.ReadMessage(nint data)
    {
        return CaptureMessage(data, extended: false);
    }

    bool IEmulationCoreEnvironmentCommands.ReadExtendedMessage(nint data)
    {
        return CaptureMessage(data, extended: true);
    }

    bool IEmulationCoreEnvironmentCommands.SetLogInterface(nint data)
    {
        return ExternalCoreEnvironmentFunctions.SetLogInterface(data, Log);
    }

    bool IEmulationCoreEnvironmentCommands.SetLedInterface(nint data)
    {
        return ExternalCoreEnvironmentFunctions.SetLedInterface(data, Led);
    }

    bool IEmulationCoreEnvironmentCommands.SetRumbleInterface(nint data)
    {
        return Feedback.Register(data);
    }

    bool IEmulationCoreEnvironmentCommands.SetSensorInterface(nint data) => false;

    bool IEmulationCoreEnvironmentCommands.WriteSystemDirectory(nint data)
    {
        return ExternalCoreEnvironmentFunctions.WritePointer(data, NativeString(SystemDirectory));
    }

    bool IEmulationCoreEnvironmentCommands.WriteContentDirectory(nint data)
    {
        return ExternalCoreEnvironmentFunctions.WritePointer(data, NativeString(ContentDirectory));
    }

    bool IEmulationCoreEnvironmentCommands.WriteSaveDirectory(nint data)
    {
        return ExternalCoreEnvironmentFunctions.WritePointer(data, NativeString(SaveDirectory));
    }

    bool IEmulationCoreEnvironmentCommands.SetSupportNoGame(nint data)
    {
        SupportsNoGame = data != nint.Zero && Marshal.ReadByte(data) != ExternalCoreInteropConstants.NativeBooleanFalse;
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.CaptureInputDescriptors(nint data)
    {
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.CaptureControllerInfo(nint data)
    {
        return CaptureControllerInfo(data);
    }

    bool IEmulationCoreEnvironmentCommands.CaptureMemoryMaps(nint data)
    {
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.SetSupportAchievements(nint data)
    {
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.ProvideVfs(nint data)
    {
        return false;
    }

    bool IEmulationCoreEnvironmentCommands.SetKeyboardCallback(nint data)
    {
        var keyboard = Marshal.PtrToStructure<ExternalCoreApi.KeyboardCallback>(data);
        _keyboardEvent = GWGUI.Emulation.Functions.ExternalCoreEnvironmentFunctions.OptionalDelegate<ExternalCoreApi.KeyboardEvent>(keyboard.Callback);
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.CaptureDiskControl(nint data)
    {
        DiskControl.Capture(data);
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.CaptureExtendedDiskControl(nint data)
    {
        DiskControl.CaptureExtended(data);
        return true;
    }

    bool IEmulationCoreEnvironmentCommands.GetDiskControlVersion(nint data)
    {
        _ = ExternalCoreEnvironmentFunctions.WriteInteger(data, 1);
        return true;
    }

    private void RegisterLegacyOptions(nint data) => OptionCatalog = CoreOptionMetadataFunctions.ReadLegacy(data, _options, _optionVisibility);

    private void RegisterVersionTwoOptions(nint options)
    {
        if (CoreOptionMetadataFunctions.ReadVersionTwo(options, _options, _optionVisibility) is { } catalog) OptionCatalog = catalog;
    }

    private bool ApplyOptionVisibility(nint data)
    {
        if (!EmulationCoreOptionFunctions.ApplyNativeVisibility(data, _optionVisibility, OptionCatalog,
                static option => option.Key, static (option, visible) => option with { IsVisible = visible },
                out var catalog)) return false;
        OptionCatalog = catalog;
        return true;
    }

    private bool CaptureOptionsDisplayCallback(nint data)
    {
        if (!EmulationCoreOptionFunctions.TryGetDisplayCallback(data, out var callback)) return false;
        _updateOptionsDisplay = callback;
        return true;
    }



    private bool ReturnOption(nint data)
    => EmulationCoreOptionFunctions.ReturnNativeValue(data, _options, (_, value) => NativeString(value));

    internal void ValidateConfiguredOptions() =>
        EmulationCoreOptionFunctions.ValidateConfiguredValues(
            _configuredOptionKeys, _options, OptionCatalog,
            static option => option.Key, static option => option.Values, static value => value.Value,
            static (key, value) => throw new InvalidDataException(CoreExceptions.InvalidOptionValue(value, key)));

    private bool CaptureMessage(nint data, bool extended)
    {
        if (data == 0) return false;
        var textPointer = Marshal.ReadIntPtr(data);
        ExternalCoreEnvironmentFunctions.CopyDiagnostic(textPointer, message => AddDiagnostic($"[message{(extended ? ExternalHostCallbacksConstants.Extended : string.Empty)}] {message}"));
        return true;
    }

    private bool CaptureControllerInfo(nint data)
    {
        if (!GWGUI.Emulation.Functions.ExternalCoreEnvironmentFunctions.TryCopyControllerPorts<IReadOnlyList<ControllerDevice>, ControllerDevice>(
            data, 16, 64, static (name, id) => new(name, id), static devices => devices,
            rejectOverflow: true, skipEmptyNames: true, out var ports)) return false;
        ControllerPorts = ports;
        return true;
    }

    private nint NativeString(string value)
    {
        if (_nativeStrings.TryGetValue(value, out var existing)) return existing.Pointer;
        return ExternalCoreUtf8String.AddTo(_nativeStrings, value, value).Pointer;
    }

}

using static GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.ControllerInputFunctions;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Constants;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Contracts;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Services;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Enums;

using System.Diagnostics;
using System.Runtime.InteropServices;
using GWGUI.Emulation;
using static GWGUI.Emulation.Sony.Emulators.Common.Interop.Constants.ExternalHostCallbacksConstants;

namespace GWGUI.Emulation.Sony.Emulators.Common.Interop.Services;

internal sealed partial class ExternalHostCallbacks
{
    internal static IReadOnlySet<EmulationKey> SupportedKeyboardKeys { get; } =
        KeyboardMap.Values.ToHashSet();

    private void HandleInputPoll()
    {
        lock (_inputGate)
        {
            _polledInput = _input.Consume();
            _pointerX = AccumulatePointerCoordinate(_pointerX, _polledInput.Pointer.DeltaX);
            _pointerY = AccumulatePointerCoordinate(_pointerY, _polledInput.Pointer.DeltaY);

        }
        PublishKeyboardTransitions(_controllerTypes.Any(type => (ControllerType)type != ControllerType.None) ? _polledInput.Keys : new HashSet<EmulationKey>());
    }

    private void PublishKeyboardTransitions(IReadOnlySet<EmulationKey> keys)
    {
        if (_keyboardEvent is null) return;
        keys = FilterReservedKeyboardChord(keys);
        var reverseMap = KeyboardMap.ToDictionary(pair => pair.Value, pair => pair.Key);
        ExternalCoreKeyboardFunctions.PublishTransitions(keys, reverseMap,
            ExternalCoreKeyboardFunctions.Modifiers(keys), ref _previousKeys, ref _keyboardEvent,
            IsModifier, CharacterFor);
    }

    internal IReadOnlySet<EmulationKey> FilterReservedKeyboardChord(IReadOnlySet<EmulationKey> keys)
    {
        var alt = keys.Contains(EmulationKey.LeftAlt) || keys.Contains(EmulationKey.RightAlt);
        var enter = keys.Contains(EmulationKey.Return) || keys.Contains(EmulationKey.NumpadEnter);
        if (alt && enter) _suppressFullscreenChord = true;
        if (!_suppressFullscreenChord) return keys;
        if (!alt && !enter) _suppressFullscreenChord = false;
        return keys.Where(key => key is not (EmulationKey.LeftAlt or EmulationKey.RightAlt or EmulationKey.Return or EmulationKey.NumpadEnter)).ToHashSet();
    }

    private static uint CharacterFor(uint code, IReadOnlySet<EmulationKey> keys)
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.Character(code, keys);

    private static bool IsModifier(EmulationKey key) => key is EmulationKey.LeftShift or EmulationKey.RightShift or EmulationKey.LeftControl or EmulationKey.RightControl or EmulationKey.LeftAlt or EmulationKey.RightAlt;

    private void HandleLog(int level, nint format, nint firstArgument, nint secondArgument)
    {
        var message = NativeLogFunctions.Read(format, firstArgument, secondArgument);
        if (!string.IsNullOrWhiteSpace(message)) AddDiagnostic($"[{level}] {message.TrimEnd()}");
    }

    private void HandleLed(int led, int state)
    {
        if (led is not (>= 0 and < 256)) return;
        _ledStates[led] = state != 0;
        if (state != 0)
            _ledActivityUntil[led] = Stopwatch.GetTimestamp() + Stopwatch.Frequency * 140 / 1000;
    }

    private void AddDiagnostic(string message)
    {
        DiagnosticMonitor.Capture(message);
        _diagnostics.Enqueue(message);
        while (_diagnostics.Count > 500) _diagnostics.TryDequeue(out _);
    }

    private short HandleInputState(uint port, uint device, uint index, uint id)
    {
        if (_controllerPorts is not null)
        {
            var portDevice = device == LightGunDevice ? LightGunDevice : JoypadDevice;
            var route = _controllerPorts.FirstOrDefault(item => item.NativePort == port && item.NativeDevice == portDevice);
            if (route is null) return default;
            port = checked((uint)route.ConfigurationPort);
        }
        if (port >= _controllerTypes.Length
            || (ControllerType)Volatile.Read(ref _controllerTypes[(int)port]) == ControllerType.None)
            return default;
        var input = _polledInput;
        var controller = port < input.Controllers.Count ? input.Controllers[(int)port] : EmulationControllerState.Empty;
        if (device == KeyboardDevice)
            return KeyboardMap.TryGetValue(id, out var key) && input.Keys.Contains(key) ? (short)1 : (short)0;

        if (device == MouseDevice)
            return (MouseInput)id switch
            {
                MouseInput.X => ClampToShort(input.Pointer.DeltaX),
                MouseInput.Y => ClampToShort(input.Pointer.DeltaY),
                MouseInput.Left => Bool(PortButton(controller, nameof(MouseAction.LeftButton), input.Pointer.Left)),
                MouseInput.Right => Bool(PortButton(controller, nameof(MouseAction.RightButton), input.Pointer.Right)),
                MouseInput.Middle => Bool(PortButton(controller, nameof(MouseAction.MiddleButton), input.Pointer.Middle)),
                MouseInput.WheelUp => Bool(input.Pointer.Wheel > NeutralWheelDelta),
                MouseInput.WheelDown => Bool(input.Pointer.Wheel < NeutralWheelDelta),
                MouseInput.HorizontalWheelUp => Bool(input.Pointer.HorizontalWheel > NeutralWheelDelta),
                MouseInput.HorizontalWheelDown => Bool(input.Pointer.HorizontalWheel < NeutralWheelDelta),
                MouseInput.Button4 => Bool(input.Pointer.ExtendedButton1),
                MouseInput.Button5 => Bool(input.Pointer.ExtendedButton2),
                _ => default
            };

        if (device == PointerDevice && index == PrimaryPointerIndex)
            return id switch
            {
                PointerX => (short)_pointerX,
                PointerY => (short)_pointerY,
                PointerPressed => Bool(input.Pointer.Left),
                PointerCount => input.Pointer.Left ? (short)SinglePointerCount : default,
                PointerOffscreen => Bool(PointerIsOffscreen()),
                _ => default
            };

        if (device == LightGunDevice)
        {
            var axisX = controller.Controls.ContainsKey(EmulationControllerCommandIds.LeftStickLeft) || controller.Controls.ContainsKey(EmulationControllerCommandIds.LeftStickRight);
            var axisY = controller.Controls.ContainsKey(EmulationControllerCommandIds.LeftStickUp) || controller.Controls.ContainsKey(EmulationControllerCommandIds.LeftStickDown);
            var x = axisX ? controller.LeftX : _pointerX;
            var y = axisY ? controller.LeftY : _pointerY;
            return (LightGunInput)id switch
            {
                LightGunInput.ScreenX => (short)x,
                LightGunInput.ScreenY => (short)y,
                LightGunInput.RelativeX => ClampToShort(input.Pointer.DeltaX),
                LightGunInput.RelativeY => ClampToShort(input.Pointer.DeltaY),
                LightGunInput.Offscreen => Bool(x <= PointerCoordinateMinimum || x >= PointerCoordinateMaximum || y <= PointerCoordinateMinimum || y >= PointerCoordinateMaximum),
                _ => Bool(LightGunButton(controller, (LightGunInput)id))
            };
        }

        if (port >= input.Controllers.Count) return 0;
        if (device == JoypadDevice)
        {
            var buttons = AnalogToggleFunctions.ButtonMask(controller, (ControllerType)_controllerTypes[(int)port]);
            if (id == JoypadMask) return unchecked((short)(buttons & ushort.MaxValue));
            return id < ControllerButtonMaskWidth && (buttons & (1u << (int)id)) != EmptyButtonMask ? Bool(true) : default;
        }
        if (device == AnalogDevice)
            return ((AnalogInputIndex)index, (AnalogAxis)id) switch
            {
                (AnalogInputIndex.LeftStick, AnalogAxis.X) => controller.LeftX,
                (AnalogInputIndex.LeftStick, AnalogAxis.Y) => controller.LeftY,
                (AnalogInputIndex.RightStick, AnalogAxis.X) => controller.RightX,
                (AnalogInputIndex.RightStick, AnalogAxis.Y) => controller.RightY,
                (AnalogInputIndex.Button, _) => AnalogButton(controller, (JoypadInput)id),
                _ => default
            };
        return 0;
    }

    private bool PointerIsOffscreen() => _pointerX <= PointerCoordinateMinimum || _pointerX >= PointerCoordinateMaximum || _pointerY <= PointerCoordinateMinimum || _pointerY >= PointerCoordinateMaximum;

    private static short Bool(bool value) => value ? (short)1 : (short)0;
    private static short ClampToShort(int value) => (short)Math.Clamp(value, short.MinValue, short.MaxValue);
    private static int AccumulatePointerCoordinate(int coordinate, int delta) => (int)Math.Clamp((long)coordinate + (long)delta * PointerCoordinateScale, PointerCoordinateMinimum, PointerCoordinateMaximum);

    private static IReadOnlyDictionary<uint, EmulationKey> CreateKeyboardMap()
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.CreateKeyMap().Where(pair => pair.Key is not (EmulationKey.LeftAmiga or EmulationKey.RightAmiga or EmulationKey.Break or EmulationKey.Undo)).ToDictionary(pair => pair.Value, pair => pair.Key);

}

using System.Runtime.InteropServices;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Constants;

namespace GWGUI.Emulation.Sony.Emulators.Common.Interop.Services;

internal sealed class HardwareRenderSession : IDisposable
{
    private OpenGlHardwareRenderContext? _hardwareRenderContext;
    private ExternalCoreApi.HardwareContextReset? _coreContextReset;
    private ExternalCoreApi.HardwareContextReset? _coreContextDestroy;
    private bool _hardwareContextReset;

    internal bool Configure(nint data)
    {
        if (data == nint.Zero) return false;
        var callback = Marshal.PtrToStructure<ExternalCoreApi.HardwareRenderCallback>(data);
        if (callback.ContextType is not (OpenGlHardwareRenderContext.OpenGlContextType
            or OpenGlHardwareRenderContext.OpenGlCoreContextType)) return false;
        var context = new OpenGlHardwareRenderContext(callback);
        try
        {
            Dispose();
            if (!context.MakeCurrentForCore()) throw new InvalidOperationException();
            _coreContextReset = GWGUI.Emulation.Functions.ExternalCoreEnvironmentFunctions.OptionalDelegate<ExternalCoreApi.HardwareContextReset>(callback.ContextReset);
            _coreContextDestroy = GWGUI.Emulation.Functions.ExternalCoreEnvironmentFunctions.OptionalDelegate<ExternalCoreApi.HardwareContextReset>(callback.ContextDestroy);
            callback.GetCurrentFramebuffer = context.CurrentFramebufferCallback;
            callback.GetProcAddress = context.ProcAddressCallback;
            Marshal.StructureToPtr(callback, data, false);
            _hardwareRenderContext = context;
            return true;
        }
        finally
        {
            if (!ReferenceEquals(_hardwareRenderContext, context)) context.Dispose();
        }
    }

    internal void Reset()
    {
        if (_hardwareRenderContext?.MakeCurrentForCore() != true) return;
        _hardwareContextReset = true;
        _coreContextReset?.Invoke();
    }

    internal void NotifyDestroy()
    {
        if (!_hardwareContextReset) return;
        _hardwareContextReset = false;
        if (_hardwareRenderContext?.MakeCurrentForCore() == true)
            _coreContextDestroy?.Invoke();
    }

    internal bool TryReadFramebuffer(int width, int height, out byte[] pixels)
    {
        pixels = [];
        return _hardwareRenderContext?.TryReadFramebuffer(width, height, out pixels) == true;
    }

    internal void Resize(int width, int height) => _hardwareRenderContext?.EnsureFramebuffer(width, height);

    public void Dispose()
    {
        try
        {
            NotifyDestroy();
        }
        finally
        {
            try { _hardwareRenderContext?.Dispose(); }
            finally
            {
                _hardwareRenderContext = null;
                _coreContextReset = _coreContextDestroy = null;
                _hardwareContextReset = false;
            }
        }
    }
}

using System.Runtime.InteropServices;

namespace GWGUI.Emulation.Sony.Emulators.Common.Interop.Services;

internal sealed class NativeControllerFeedback : IDisposable
{
    private const uint StrongEffect = 0;
    private const uint WeakEffect = 1;
    private readonly object _gate = new();
    private readonly ushort[,] _values = new ushort[ControllerPortConstants.MaximumGamepadPortCount, 2];
    private readonly ExternalCoreApi.SetRumbleState _setState;
    private bool _disposed;

    internal NativeControllerFeedback() => _setState = SetState;

    internal bool Register(nint destination)
    {
        if (destination == nint.Zero) return false;
        lock (_gate)
        {
            if (_disposed) return false;
            Marshal.StructureToPtr(new ExternalCoreApi.RumbleInterface { SetState = Marshal.GetFunctionPointerForDelegate(_setState) }, destination, false);
            return true;
        }
    }

    internal bool SetState(uint port, uint effect, ushort strength)
    {
        if (port >= ControllerPortConstants.MaximumGamepadPortCount || effect > WeakEffect) return false;
        lock (_gate)
        {
            if (_disposed) return false;
            _values[port, effect] = strength;
            return true;
        }
    }

    internal IReadOnlyList<ControllerFeedbackState> Snapshot()
    {
        lock (_gate)
        {
            if (_disposed) return [];
            var result = new List<ControllerFeedbackState>();
            for (var port = 0; port < ControllerPortConstants.MaximumGamepadPortCount; port++)
            {
                if (_values[port, StrongEffect] != 0)
                    result.Add(new(port, EmulationControllerFeedbackCommands.Strong, _values[port, StrongEffect] / (float)ushort.MaxValue));
                if (_values[port, WeakEffect] != 0)
                    result.Add(new(port, EmulationControllerFeedbackCommands.Weak, _values[port, WeakEffect] / (float)ushort.MaxValue));
            }
            return result;
        }
    }

    internal void ResetPort(int port)
    {
        if (port is < 0 or >= ControllerPortConstants.MaximumGamepadPortCount) return;
        lock (_gate)
        {
            _values[port, StrongEffect] = 0;
            _values[port, WeakEffect] = 0;
        }
    }

    public void Dispose()
    {
        lock (_gate)
        {
            _disposed = true;
            Array.Clear(_values);
        }
    }
}

