using NativeControllerFunctions = GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.ControllerPortFunctions;
using NativeControllerDevice = GWGUI.Emulation.Sony.Emulators.Common.Interop.Contracts.ControllerDevice;
using NativeMemoryCards = GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.MemoryCardFunctions;
using NativeFirmware = GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.FirmwareRuntimeFunctions;
using FirmwareConstants = GWGUI.Emulation.Sony.Emulators.Pcsx2.Constants.FirmwareConstants;

namespace GWGUI.Emulation.Sony.Emulators.Pcsx2.Services;

internal sealed class ExternalCore : IEmulatorCore
{
    private readonly string _corePath;
    private ExternalCoreLibrary? _library;
    private ExternalHostCallbacks? _host;
    private ExternalCoreApi.VoidCall? _deinitialize;
    private ExternalCoreApi.VoidCall? _unloadGame;
    private ExternalCoreApi.VoidCall? _run;
    private ExternalCoreApi.VoidCall? _reset;
    private ExternalCoreApi.SetControllerPortDevice? _setControllerPortDevice;
    private ExternalCoreApi.GetSerializedSize? _getSerializedSize;
    private ExternalCoreApi.Serialize? _serialize;
    private ExternalCoreApi.Serialize? _unserialize;
    private MachineConfiguration? _configuration;
    private string? _sessionDirectory;
    private string? _saveDirectory;
    private bool _gameLoaded;
    private bool _initialized;
    private bool _disposing;
    private readonly List<(string Source, string Native)> _memoryCardFiles = [];
    private IReadOnlyList<(string Source, string Native, int Size)> _firmwareFiles = [];

    internal ExternalCore(string corePath) => _corePath = corePath;

    public VideoFrame? LatestVideoFrame => _host?.LatestVideoFrame;
    public AudioChunk? LatestAudioChunk => _host?.LatestAudioChunk;
    public IReadOnlyList<CoreOption> Options => _host?.OptionCatalog ?? [];
    public IReadOnlyList<string> Diagnostics => _host?.Diagnostics ?? [];
    public IReadOnlyDictionary<int, bool> LedStates => _host?.LedStates ?? new Dictionary<int, bool>();
    public bool ShutdownRequested => _host?.ShutdownRequested ?? false;
    public IReadOnlyList<ControllerFeedbackState> ControllerFeedback => _host?.Feedback.Snapshot() ?? [];
    public string CoreName { get; private set; } = string.Empty;
    public string CoreVersion { get; private set; } = string.Empty;
    public IReadOnlySet<string> SupportedContentExtensions { get; private set; } =
        new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public string CoreSha256 { get; private set; } = string.Empty;
    public double FramesPerSecond => _host?.FramesPerSecond ?? 50d;
    public int SampleRate => _host?.SampleRate ?? 44_100;
    public int DiskCount => _host?.DiskControl.ImageCount ?? 0;
    public int CurrentDiskIndex => _host?.DiskControl.CurrentIndex ?? -1;

    public bool TryDequeueAudio(out AudioChunk? chunk)
    {
        if (_host is not null) return _host.TryDequeueAudio(out chunk);
        chunk = null;
        return false;
    }

    public void Initialize(MachineConfiguration configuration, string sessionDirectory, string? saveDirectory = null)
    {
        Functions.FileSystemFunctions.Validate(configuration);
        configuration = Functions.HardDiskRuntimeFunctions.Configure(configuration);
        _configuration = configuration;
        _sessionDirectory = Path.GetFullPath(sessionDirectory);
        _saveDirectory = saveDirectory is null ? null : Path.GetFullPath(saveDirectory);
        var media = ResolveConfiguredMedia(configuration);
        foreach (var item in media)
            if (!File.Exists(item.Path))
                throw new FileNotFoundException(Pcsx2Exceptions.MediaNotFound(), item.Path);

        var sourceCorePath = ResolveCorePath(_corePath);
        using (var stream = File.OpenRead(sourceCorePath))
            CoreSha256 = Convert.ToHexString(SHA256.HashData(stream));

        var systemDirectory = Path.Combine(sessionDirectory, CoreDirectoryConstants.SystemDirectoryName);
        var contentDirectory = Path.Combine(sessionDirectory, CoreDirectoryConstants.ContentDirectoryName);
        saveDirectory = Path.GetFullPath(saveDirectory ?? Path.Combine(sessionDirectory, CoreDirectoryConstants.SavesDirectoryName));
        Directory.CreateDirectory(systemDirectory);
        NativeMemoryCards.PreparePs2(configuration, systemDirectory, _memoryCardFiles);
        FirmwareConfigurationFunctions.CopySelectedFiles(configuration, new GWGUI.Emulation.Sony.Emulators.Pcsx2.Factories.Pcsx2MachineFactory(), systemDirectory);
        _firmwareFiles = NativeFirmware.Prepare(configuration, Pcsx2Constants.Id, FirmwareConstants.Persistence, systemDirectory, saveDirectory);
        Directory.CreateDirectory(contentDirectory);
        Directory.CreateDirectory(saveDirectory);
        var isolatedCoreDirectory = Path.Combine(sessionDirectory, ExternalCoreConstants.CoreDirectory);
        Directory.CreateDirectory(isolatedCoreDirectory);
        var isolatedCorePath = Path.Combine(isolatedCoreDirectory, ExternalCoreConstants.LibraryName);
        File.Copy(sourceCorePath, isolatedCorePath, true);
        var contentPath = PrepareContentPath(media, contentDirectory);
        var nativeSystemDirectory = Functions.FileSystemFunctions.SystemDirectory(configuration, systemDirectory);
        Func<string, (string Path, bool IsReadOnly)>? pathResolver = nativeSystemDirectory == systemDirectory
            ? null : path => Functions.FileSystemFunctions.Resolve(configuration, systemDirectory, path, _host?.CheatsEnabled);
        _host = new ExternalHostCallbacks(systemDirectory, contentDirectory, saveDirectory, configuration.Options ?? new Dictionary<string, string>(),
            nativeSystemDirectory, pathResolver);

        try
        {
            _library = new ExternalCoreLibrary(isolatedCorePath);
            var apiVersion = Export<ExternalCoreApi.GetApiVersion>(ExternalCoreConstants.RetroApiVersion)();
            if (apiVersion != ExternalCoreInteropConstants.ApiVersion)
                throw new NotSupportedException(Pcsx2Exceptions.UnsupportedApiVersion(apiVersion));
            Export<ExternalCoreApi.GetSystemInfo>(ExternalCoreConstants.RetroGetSystemInfo)(out var info);
            var libraryName = Marshal.PtrToStringUTF8(info.LibraryName);
            if (!string.Equals(libraryName, Pcsx2Constants.LibraryName, StringComparison.OrdinalIgnoreCase)
                && !string.Equals(libraryName, Pcsx2Constants.CurrentLibraryName, StringComparison.OrdinalIgnoreCase))
                throw new InvalidDataException(Pcsx2Exceptions.LibraryIdentityMismatch(libraryName));
            if (!info.NeedFullPath)
                throw new InvalidDataException(Pcsx2Exceptions.FullContentPathsRequired());
            CoreName = libraryName!;
            CoreVersion = Marshal.PtrToStringUTF8(info.LibraryVersion) ?? string.Empty;
            SupportedContentExtensions = ExternalCoreLibrary.ParseExtensions(info.ValidExtensions);
            ValidateExtension(contentPath);

            Export<ExternalCoreApi.SetEnvironment>(ExternalCoreConstants.RetroSetEnvironment)(_host.Environment);
            Export<ExternalCoreApi.SetVideo>(ExternalCoreConstants.RetroSetVideoRefresh)(_host.Video);
            Export<ExternalCoreApi.SetAudioSample>(ExternalCoreConstants.RetroSetAudioSample)(_host.AudioSample);
            Export<ExternalCoreApi.SetAudioBatch>(ExternalCoreConstants.RetroSetAudioSampleBatch)(_host.AudioBatch);
            Export<ExternalCoreApi.SetInputPoll>(ExternalCoreConstants.RetroSetInputPoll)(_host.InputPoll);
            Export<ExternalCoreApi.SetInputState>(ExternalCoreConstants.RetroSetInputState)(_host.InputState);
            _deinitialize = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroDeinit);
            _unloadGame = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroUnloadGame);
            _run = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroRun);
            _reset = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroReset);
            _getSerializedSize = Export<ExternalCoreApi.GetSerializedSize>(ExternalCoreConstants.RetroSerializeSize);
            _serialize = Export<ExternalCoreApi.Serialize>(ExternalCoreConstants.RetroSerialize);
            _unserialize = Export<ExternalCoreApi.Serialize>(ExternalCoreConstants.RetroUnserialize);
            Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroInit)();
            _initialized = true;
            _host.ValidateConfiguredOptions();
            _setControllerPortDevice = Export<ExternalCoreApi.SetControllerPortDevice>(ExternalCoreConstants.RetroSetControllerPortDevice);
            ApplyConfiguredControllers(requireAdvertised: false);

            var loadGame = Export<ExternalCoreApi.LoadGame>(ExternalCoreConstants.RetroLoadGame);
            if (contentPath is null)
            {
                if (!_host.SupportsNoGame)
                    throw new InvalidOperationException(Pcsx2Exceptions.StartWithoutMediaUnsupported());
                _gameLoaded = loadGame(0);
            }
            else _gameLoaded = LoadGame(loadGame, contentPath);
            if (!_gameLoaded) throw new InvalidOperationException(Pcsx2Exceptions.ContentRefused());
            ApplyConfiguredControllers(requireAdvertised: true);
            Export<ExternalCoreApi.GetSystemAvInfo>(ExternalCoreConstants.RetroGetSystemAvInfo)(out var av);
            _host.ApplyInitialAvInfo(av);
            _host.HardwareRender.Reset();
        }
        catch
        {
            Dispose();
            throw;
        }
    }

    internal static IReadOnlyList<MediaConfiguration> ResolveConfiguredMedia(MachineConfiguration configuration) => (configuration.Media ?? []).Where(item => item.IsInserted && item.Category != MediaCategory.HardDisk).OrderBy(item => item.MountOrder).ToArray();

    internal static string? PrepareContentPath(IReadOnlyList<MediaConfiguration> media, string contentDirectory)
    {
        if (media.Count == 0) return null;
        if (media.Count == 1 || media.Any(item => item.Category != MediaCategory.Floppy))
            return Path.GetFullPath(media[0].Path);
        if (media.Count > ExternalCoreConstants.MaximumPlaylistEntries)
            throw new ArgumentOutOfRangeException(nameof(media), Pcsx2Exceptions.PlaylistLimitExceeded());
        var playlist = Path.Combine(contentDirectory, ExternalCoreConstants.PlaylistName);
        File.WriteAllLines(playlist, media.Select(item => Path.GetFullPath(item.Path)), new System.Text.UTF8Encoding(false));
        return playlist;
    }

    public void RunFrame() => (_run ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized()))();
    public void HardReset()
    {
        var configuration = _configuration ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized());
        var sessionDirectory = _sessionDirectory ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized());
        var saveDirectory = _saveDirectory;
        Dispose();
        Initialize(configuration, sessionDirectory, saveDirectory);
    }
    public void SoftReset() => (_reset ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized()))();
    public void SetInput(EmulationInputSnapshot snapshot)
    {
        if (_host is not null) _host.Input = snapshot;
    }
    public void SetControllerPortDevice(int port, ControllerType type)
    {
        var configuration = _configuration ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized());
        var host = _host ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized());
        var setter = _setControllerPortDevice ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized());
        ControllerFunctions.Validate(configuration, port, type);
        var nativePorts = host.ControllerPorts.Select(devices => (IReadOnlyList<NativeControllerDevice>)devices.Select(device => new NativeControllerDevice(device.Name, device.Id)).ToArray()).ToArray();
        var nativeType = InputSettingsFunctions.NativeUsbType(configuration, port, type);
        var nativeId = NativeControllerFunctions.Resolve(nativeType, port, nativePorts);
        setter((uint)port, nativeId);
        host.SetControllerType(port, nativeType);
        host.Feedback.ResetPort(port);
        _configuration = ControllerFunctions.WithControllerType(configuration, port, type);
    }

    private void ApplyConfiguredControllers(bool requireAdvertised)
    {
        var configuration = _configuration ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized());
        for (var port = ControllerPortConstants.MinimumControllerPort;
            port < ControllerFunctions.PortCount(configuration); port++)
        {
            var type = ControllerFunctions.Resolve(configuration, port);
            if (!requireAdvertised && !_host!.ControllerPorts.Any()
                && type is not (ControllerType.Joystick or ControllerType.DanceMat or ControllerType.ArcadeStick or ControllerType.None)) continue;
            SetControllerPortDevice(port, type);
        }
    }
    public void InsertMedia(string path) => (_host ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized())).DiskControl.Insert(path);
    public void EjectMedia() => (_host ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized())).DiskControl.Eject();
    public void SelectDisk(int index) => (_host ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized())).DiskControl.Select(index);

    public byte[] SaveState()
    {
        var size = (_getSerializedSize ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized()))();
        if (size == ExternalCoreInteropConstants.EmptyNativeSize || size > SavedStateConstants.MaximumStateSize)
            throw new InvalidOperationException(Pcsx2Exceptions.InvalidStateSize(size));
        var state = new byte[(int)size];
        var buffer = Marshal.AllocHGlobal(state.Length);
        try
        {
            if (!_serialize!(buffer, size))
                throw new InvalidOperationException(Pcsx2Exceptions.StateSaveFailed());
            Marshal.Copy(buffer, state, BufferConstants.FirstBufferIndex, state.Length);
        }
        finally { Marshal.FreeHGlobal(buffer); }
        return state;
    }

    public void LoadState(ReadOnlySpan<byte> state)
    {
        if (state.IsEmpty) throw new ArgumentException(Pcsx2Exceptions.StateEmpty(), nameof(state));
        var bytes = state.ToArray();
        var buffer = Marshal.AllocHGlobal(bytes.Length);
        try
        {
            Marshal.Copy(bytes, BufferConstants.FirstBufferIndex, buffer, bytes.Length);
            if (!_unserialize!(buffer, (nuint)bytes.Length))
                throw new InvalidOperationException(Pcsx2Exceptions.StateRestoreFailed());
        }
        finally { Marshal.FreeHGlobal(buffer); }
    }

    public void SetOption(string key, string value) => (_host ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotInitialized())).SetOption(key, value);

    public void Stop()
    {
        if (!_gameLoaded) return;
        _gameLoaded = false;
        try
        {
            try { _host?.HardwareRender.NotifyDestroy(); }
            finally { _unloadGame?.Invoke(); }
        }
        finally
        {
            try { NativeMemoryCards.PersistFiles(_memoryCardFiles, StorageSettingsFunctionsConstants.Ps2MemoryCardSize); }
            finally { _memoryCardFiles.Clear(); }
        }
    }

    private void ValidateExtension(string? path)
    {
        if (path is null) return;
        var extension = Path.GetExtension(path).TrimStart(MediaConstants.ExtensionPrefix);
        if (!SupportedContentExtensions.Contains(extension))
            throw new InvalidDataException(Pcsx2Exceptions.UnsupportedContentExtension(extension));
    }

    private static bool LoadGame(ExternalCoreApi.LoadGame loadGame, string path)
    {
        using var nativePath = new ExternalCoreUtf8String(path);
        var game = Marshal.AllocHGlobal(Marshal.SizeOf<ExternalCoreApi.GameInfo>());
        try
        {
            Marshal.StructureToPtr(new ExternalCoreApi.GameInfo { Path = nativePath.Pointer }, game, false);
            return loadGame(game);
        }
        finally { Marshal.FreeHGlobal(game); }
    }

    private T Export<T>(string name) where T : Delegate => (_library ?? throw new InvalidOperationException(Pcsx2Exceptions.CoreNotLoaded())).Resolve<T>(name);

    private static string ResolveCorePath(string path)
    {
        if (!Path.IsPathFullyQualified(path))
            throw new ArgumentException(Pcsx2Exceptions.CorePathNotAbsolute(), nameof(path));
        if (!File.Exists(path)) throw new FileNotFoundException(Pcsx2Exceptions.CoreNotFound(), path);
        return path;
    }

    public void Dispose()
    {
        if (_disposing) return;
        _disposing = true;
        try
        {
            var callbacks = _host;
            try { _host?.HardwareRender.NotifyDestroy(); }
            finally
            {
                try { Stop(); }
                finally
                {
                    try
                    {
                        if (_initialized) _deinitialize?.Invoke();
                    }
                    finally
                    {
                        _initialized = false;
                        _deinitialize = null;
                        _unloadGame = null;
                        _run = null;
                        _reset = null;
                        _setControllerPortDevice = null;
                        _getSerializedSize = null;
                        _serialize = null;
                        _unserialize = null;
                        try { NativeFirmware.Persist(_firmwareFiles); }
                        finally
                        {
                            _firmwareFiles = [];
                            try { _host?.Dispose(); }
                            finally
                            {
                                _host = null;
                                try { _library?.Dispose(); }
                                finally { GC.KeepAlive(callbacks); _library = null; }
                            }
                        }
                    }
                }

            }

        }
        finally { _disposing = false; }
    }
}

