internal sealed partial class ExternalHostCallbacks
{
    internal static IReadOnlySet<EmulationKey> SupportedKeyboardKeys { get; } =
        KeyboardMap.Values.ToHashSet();

    private void HandleInputPoll()
    {
        lock (_inputGate)
        {
            _polledInput = _input.Consume();
            _pointerX = AccumulatePointerCoordinate(_pointerX, _polledInput.Pointer.DeltaX);
            _pointerY = AccumulatePointerCoordinate(_pointerY, _polledInput.Pointer.DeltaY);

        }
        PublishKeyboardTransitions(_controllerTypes.Any(type => (ControllerType)type != ControllerType.None) ? _polledInput.Keys : new HashSet<EmulationKey>());
    }

    private void PublishKeyboardTransitions(IReadOnlySet<EmulationKey> keys)
    {
        if (_keyboardEvent is null) return;
        keys = FilterReservedKeyboardChord(keys);
        var reverseMap = KeyboardMap.ToDictionary(pair => pair.Value, pair => pair.Key);
        ExternalCoreKeyboardFunctions.PublishTransitions(keys, reverseMap,
            ExternalCoreKeyboardFunctions.Modifiers(keys), ref _previousKeys, ref _keyboardEvent,
            IsModifier, CharacterFor);
    }

    internal IReadOnlySet<EmulationKey> FilterReservedKeyboardChord(IReadOnlySet<EmulationKey> keys)
    {
        var alt = keys.Contains(EmulationKey.LeftAlt) || keys.Contains(EmulationKey.RightAlt);
        var enter = keys.Contains(EmulationKey.Return) || keys.Contains(EmulationKey.NumpadEnter);
        if (alt && enter) _suppressFullscreenChord = true;
        if (!_suppressFullscreenChord) return keys;
        if (!alt && !enter) _suppressFullscreenChord = false;
        return keys.Where(key => key is not (EmulationKey.LeftAlt or EmulationKey.RightAlt or EmulationKey.Return or EmulationKey.NumpadEnter)).ToHashSet();
    }

    private static uint CharacterFor(uint code, IReadOnlySet<EmulationKey> keys)
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.Character(code, keys);

    private static bool IsModifier(EmulationKey key) => key is EmulationKey.LeftShift or EmulationKey.RightShift or EmulationKey.LeftControl or EmulationKey.RightControl or EmulationKey.LeftAlt or EmulationKey.RightAlt;

    private void HandleLog(int level, nint format, nint firstArgument, nint secondArgument)
    {
        var message = NativeLogFunctions.Read(format, firstArgument, secondArgument);
        if (!string.IsNullOrWhiteSpace(message)) AddDiagnostic($"[{level}] {message.TrimEnd()}");
    }

    private void HandleLed(int led, int state)
    {
        if (led is not (>= 0 and < 256)) return;
        _ledStates[led] = state != 0;
        if (state != 0)
            _ledActivityUntil[led] = Stopwatch.GetTimestamp() + Stopwatch.Frequency * 140 / 1000;
    }

    private void AddDiagnostic(string message)
    {
        _diagnostics.Enqueue(message);
        while (_diagnostics.Count > 500) _diagnostics.TryDequeue(out _);
    }

    private short HandleInputState(uint port, uint device, uint index, uint id)
    {
        if (port >= _controllerTypes.Length
            || (ControllerType)Volatile.Read(ref _controllerTypes[(int)port]) == ControllerType.None)
            return default;
        var input = _polledInput;
        var controller = port < input.Controllers.Count ? input.Controllers[(int)port] : EmulationControllerState.Empty;
        if (device == KeyboardDevice)
            return KeyboardMap.TryGetValue(id, out var key) && input.Keys.Contains(key) ? (short)1 : (short)0;

        if (device == MouseDevice)
            return (MouseInput)id switch
            {
                MouseInput.X => ClampToShort(input.Pointer.DeltaX),
                MouseInput.Y => ClampToShort(input.Pointer.DeltaY),
                MouseInput.Left => Bool(PortButton(controller, nameof(MouseAction.LeftButton), input.Pointer.Left)),
                MouseInput.Right => Bool(PortButton(controller, nameof(MouseAction.RightButton), input.Pointer.Right)),
                MouseInput.Middle => Bool(PortButton(controller, nameof(MouseAction.MiddleButton), input.Pointer.Middle)),
                MouseInput.WheelUp => Bool(input.Pointer.Wheel > InputConstants.NeutralWheelDelta),
                MouseInput.WheelDown => Bool(input.Pointer.Wheel < InputConstants.NeutralWheelDelta),
                MouseInput.HorizontalWheelUp => Bool(input.Pointer.HorizontalWheel > InputConstants.NeutralWheelDelta),
                MouseInput.HorizontalWheelDown => Bool(input.Pointer.HorizontalWheel < InputConstants.NeutralWheelDelta),
                MouseInput.Button4 => Bool(input.Pointer.ExtendedButton1),
                MouseInput.Button5 => Bool(input.Pointer.ExtendedButton2),
                _ => default
            };
        if (device == PointerDevice && port == 0)
            return id switch
            {
                PointerX => (short)_pointerX,
                PointerY => (short)_pointerY,
                PointerPressed => Bool(input.Pointer.Left),
                _ => 0
            };

        if (port >= input.Controllers.Count) return 0;

        if (device == JoypadDevice)
        {
            var buttons = controller.Buttons;
            if (id == JoypadMask) return unchecked((short)(buttons & ushort.MaxValue));
            return id < 32 && (buttons & (1u << (int)id)) != 0 ? (short)1 : (short)0;
        }
        if (device == AnalogDevice)
            return ((AnalogInputIndex)index, (AnalogAxis)id) switch
            {
                (AnalogInputIndex.LeftStick, AnalogAxis.X) => controller.LeftX,
                (AnalogInputIndex.LeftStick, AnalogAxis.Y) => controller.LeftY,
                (AnalogInputIndex.RightStick, AnalogAxis.X) => controller.RightX,
                (AnalogInputIndex.RightStick, AnalogAxis.Y) => controller.RightY,
                (AnalogInputIndex.Button, _) => AnalogButton(controller, (JoypadInput)id),
                _ => default
            };
        return 0;
    }

    private static short Bool(bool value) => value ? (short)1 : (short)0;
    private static short ClampToShort(int value) => (short)Math.Clamp(value, short.MinValue, short.MaxValue);
    private static int AccumulatePointerCoordinate(int coordinate, int delta) => (int)Math.Clamp((long)coordinate + (long)delta * PointerCoordinateScale, PointerCoordinateMinimum, PointerCoordinateMaximum);

    private static IReadOnlyDictionary<uint, EmulationKey> CreateKeyboardMap()
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.CreateKeyMap().Where(pair => pair.Key is not (EmulationKey.LeftAmiga or EmulationKey.RightAmiga or EmulationKey.Break or EmulationKey.Undo)).ToDictionary(pair => pair.Value, pair => pair.Key);

}

using ControllerFeedbackProtocol = GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.ControllerFeedbackProtocol;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Exceptions;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Enums;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Constants;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Contracts;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Factories;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Functions;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Services;

using CoreOptionMetadataFunctions = GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.CoreOptionMetadataFunctions;
using System.IO;
using System.Collections.Concurrent;
using System.Buffers.Binary;
using System.Diagnostics;
using System.IO.Pipes;
using System.IO.MemoryMappedFiles;
using System.Text.Json;
using GWGUI.Emulation;
using GWGUI.Emulation.Functions;

namespace GWGUI.Emulation.Sony.Emulators.Pcsx2.Services;

internal sealed class ProcessCore : IEmulatorCore
{
    private readonly string _hostExecutablePath;
    private readonly string? _corePath;
    private readonly ConcurrentQueue<AudioChunk> _audio = new();
    private NamedPipeServerStream? _pipe;
    private BinaryReader? _responseReader;
    private BinaryWriter? _writer;
    private Process? _process;
    private MemoryMappedFile? _videoMemory;
    private MemoryMappedViewAccessor? _videoMap;
    private readonly InputAccumulator _input = new();
    private bool _initialized;
    private bool _disposed;
    private bool _connectionFailed;
    private MachineConfiguration? _configuration;
    private string? _sessionDirectory;
    private string? _saveDirectory;

    internal ProcessCore(string hostExecutablePath, string? corePath = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(hostExecutablePath);
        _hostExecutablePath = Path.GetFullPath(hostExecutablePath);
        _corePath = corePath;
    }

    public VideoFrame? LatestVideoFrame { get; private set; }
    public AudioChunk? LatestAudioChunk { get; private set; }
    public IReadOnlyList<CoreOption> Options { get; private set; } = [];
    public IReadOnlyList<string> Diagnostics { get; private set; } = [];
    public IReadOnlyDictionary<int, bool> LedStates { get; private set; } = new Dictionary<int, bool>();
    public bool ShutdownRequested { get; private set; }
    public IReadOnlyList<ControllerFeedbackState> ControllerFeedback { get; private set; } = [];
    public string CoreName { get; private set; } = string.Empty;
    public string CoreVersion { get; private set; } = string.Empty;
    public IReadOnlySet<string> SupportedContentExtensions { get; private set; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public string CoreSha256 { get; private set; } = string.Empty;
    public double FramesPerSecond { get; private set; } = 50;
    public int SampleRate { get; private set; } = 44100;
    public int DiskCount { get; private set; }
    public int CurrentDiskIndex { get; private set; } = -1;

    public bool TryDequeueAudio(out AudioChunk? chunk)
    => _audio.TryDequeue(out chunk);

    public void Initialize(MachineConfiguration configuration, string sessionDirectory, string? saveDirectory = null)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (_initialized) throw new InvalidOperationException(Pcsx2Exceptions.ProcessAlreadyInitialized());
        if (!File.Exists(_hostExecutablePath))
            throw new FileNotFoundException(Pcsx2Exceptions.HostExecutableNotFound(), _hostExecutablePath);

        _configuration = configuration;
        _sessionDirectory = Path.GetFullPath(sessionDirectory);
        _saveDirectory = saveDirectory is null ? null : Path.GetFullPath(saveDirectory);
        var pipeName = $"{ProcessCoreConstants.PipePrefix}{Guid.NewGuid():N}";
        var videoMapName = $"{ProcessCoreConstants.VideoMapPrefix}{Guid.NewGuid():N}";
        _videoMemory = MemoryMappedFile.CreateNew(videoMapName, EmulationHostProtocolConstants.VideoMapCapacity, MemoryMappedFileAccess.ReadWrite);
        try
        {
            _videoMap = _videoMemory.CreateViewAccessor(0, EmulationHostProtocolConstants.VideoMapCapacity, MemoryMappedFileAccess.ReadWrite);
            _pipe = new NamedPipeServerStream(pipeName, PipeDirection.InOut, 1, PipeTransmissionMode.Byte, PipeOptions.Asynchronous, ProcessCoreConstants.PipeBufferSize, ProcessCoreConstants.PipeBufferSize);
            var startInfo = new ProcessStartInfo(_hostExecutablePath)
            {
                UseShellExecute = false,
                CreateNoWindow = true,
                WorkingDirectory = Path.GetDirectoryName(_hostExecutablePath)!
            };
            startInfo.ArgumentList.Add(ProcessCoreConstants.CoreHost);
            startInfo.ArgumentList.Add(pipeName);
            startInfo.ArgumentList.Add(videoMapName);
            _process = EmulationChildProcessLifetime.Start(startInfo, () => new InvalidOperationException(Pcsx2Exceptions.ProcessStartFailed()));
            EmulationHostProtocolFunctions.WaitForConnection(_pipe, TimeSpan.FromSeconds(15));
            _writer = new BinaryWriter(_pipe, System.Text.Encoding.UTF8, true);
            Begin(HostCommand.Initialize);
            EmulationHostProtocolFunctions.WriteInitializationRequest(ref _writer, _corePath ?? string.Empty,
                () => _sessionDirectory,
                () => _saveDirectory,
                CoreHostProtocol.WriteString,
                () => JsonSerializer.Serialize(configuration, CoreHostProtocol.JsonOptions));
            CompleteRequest();
            CoreSha256 = Response.ReadString();
            FramesPerSecond = Response.ReadDouble();
            SampleRate = Response.ReadInt32();
            Options = JsonSerializer.Deserialize<IReadOnlyList<CoreOption>>(Response.ReadString(), CoreHostProtocol.JsonOptions) ?? [];
            Options = CoreOptionMetadataFunctions.Merge(Options, Dictionaries.OptionCatalog.All, configuration.GraphicsApi);
            Diagnostics = JsonSerializer.Deserialize<IReadOnlyList<string>>(Response.ReadString(), CoreHostProtocol.JsonOptions) ?? [];
            CoreName = Response.ReadString();
            CoreVersion = Response.ReadString();
            SupportedContentExtensions = Response.ReadString().Split('|', StringSplitOptions.RemoveEmptyEntries).ToHashSet(StringComparer.OrdinalIgnoreCase);
            DiskCount = Response.ReadInt32();
            CurrentDiskIndex = Response.ReadInt32();
            LedStates = CoreHostProtocol.ReadLedStates(Response);
            ShutdownRequested = Response.ReadBoolean();
            ControllerFeedback = ControllerFeedbackProtocol.Read(Response);
            _initialized = true;
        }
        finally
        {
            if (!_initialized) ReleaseHost();
        }
    }

    public void RunFrame()
    {
        Begin(HostCommand.RunFrame);
        CoreHostProtocol.WriteInput(_writer!, _input.Consume());
        CompleteRequest();
        LatestVideoFrame = CoreHostProtocol.ReadSharedFrame(Response, _videoMap ?? throw new InvalidOperationException(Pcsx2Exceptions.VideoBufferUnavailable())) ?? LatestVideoFrame;
        foreach (var chunk in CoreHostProtocol.ReadAudio(Response))
        {
            LatestAudioChunk = chunk;
            _audio.Enqueue(chunk);
        }
        FramesPerSecond = Response.ReadDouble();
        SampleRate = Response.ReadInt32();
        DiskCount = Response.ReadInt32();
        CurrentDiskIndex = Response.ReadInt32();
        if (Response.ReadBoolean())
            Diagnostics = JsonSerializer.Deserialize<IReadOnlyList<string>>(Response.ReadString(), CoreHostProtocol.JsonOptions) ?? [];
        LedStates = CoreHostProtocol.ReadLedStates(Response);
        ShutdownRequested = Response.ReadBoolean();
        ControllerFeedback = ControllerFeedbackProtocol.Read(Response);
    }

    public void HardReset()
    {
        var configuration = _configuration ?? throw new InvalidOperationException(Pcsx2Exceptions.ProcessNotInitialized());
        var sessionDirectory = _sessionDirectory ?? throw new InvalidOperationException(Pcsx2Exceptions.ProcessNotInitialized());
        var saveDirectory = _saveDirectory;
        ReleaseHost();
        Initialize(configuration, sessionDirectory, saveDirectory);
    }
    public void SoftReset() => SimpleRequest(HostCommand.SoftReset);
    public void Stop() => SimpleRequest(HostCommand.Stop);
    public void SetInput(EmulationInputSnapshot snapshot) => _input.Update(snapshot);
    public void InsertMedia(string path) => StringRequest(HostCommand.InsertMedia, Path.GetFullPath(path));
    public void EjectMedia() => SimpleRequest(HostCommand.EjectMedia);

    public void SelectDisk(int index)
    {
        Begin(HostCommand.SelectDisk);
        _writer!.Write(index);
        CompleteRequest();
        CurrentDiskIndex = index;
    }

    public byte[] SaveState()
    {
        Begin(HostCommand.SaveState);
        CompleteRequest();
        return CoreHostProtocol.ReadBytes(Response);
    }

    public void LoadState(ReadOnlySpan<byte> state)
    {
        Begin(HostCommand.LoadState);
        CoreHostProtocol.WriteBytes(_writer!, state);
        CompleteRequest();
    }

    public void SetOption(string key, string value)
    {
        Begin(HostCommand.SetOption);
        _writer!.Write(key);
        _writer.Write(value);
        CompleteRequest();
    }

    public void SetControllerPortDevice(int port, ControllerType type)
    {
        var configuration = _configuration ?? throw new InvalidOperationException(Pcsx2Exceptions.ProcessNotInitialized());
        ControllerFunctions.Validate(configuration, port, type);
        Begin(HostCommand.SetControllerPortDevice);
        _writer!.Write(port);
        _writer.Write((int)type);
        CompleteRequest();
        _configuration = ControllerFunctions.WithControllerType(configuration, port, type);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        ReleaseHost();
    }

    private void ReleaseHost()
    {
        try
        {
            if (!_connectionFailed && _pipe?.IsConnected == true)
            {
                try
                {
                    _writer!.Write((byte)HostCommand.Dispose);
                    CompleteRequest();
                }
                catch (Exception) { }
            }
        }
        finally
        {
            DisposeSafely(_responseReader); _responseReader = null;
            DisposeSafely(_writer); _writer = null;
            DisposeSafely(_pipe); _pipe = null;
            DisposeSafely(_videoMap); _videoMap = null;
            DisposeSafely(_videoMemory); _videoMemory = null;
            var process = _process;
            _process = null;
            try
            {
                if (process is not null) WaitForProcessExit(process, graceful: true);
            }
            finally
            {
                DisposeSafely(process);
                while (_audio.TryDequeue(out _)) { }
                LatestVideoFrame = null;
                LatestAudioChunk = null;
                Options = [];
                Diagnostics = [];
                ShutdownRequested = false;
                ControllerFeedback = [];
                LedStates = new Dictionary<int, bool>();
                DiskCount = 0;
                CurrentDiskIndex = -1;
                _input.Reset();
                _initialized = false;
                _connectionFailed = false;
            }
        }
    }

    private void StringRequest(HostCommand command, string value)
    {
        Begin(command);
        _writer!.Write(value);
        CompleteRequest();
    }

    private void SimpleRequest(HostCommand command)
    {
        Begin(command);
        CompleteRequest();
    }

    private void Begin(HostCommand command)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (_connectionFailed) throw new InvalidOperationException(Pcsx2Exceptions.ProcessUnavailable());
        if (command != HostCommand.Initialize && !_initialized)
            throw new InvalidOperationException(Pcsx2Exceptions.ProcessNotInitialized());
        _writer!.Write((byte)command);
    }

    private void CompleteRequest()
    {
        try
        {
            var response = ReadResponseAsync().GetAwaiter().GetResult();
            _responseReader?.Dispose();
            _responseReader = new BinaryReader(new MemoryStream(response, false), System.Text.Encoding.UTF8, false);
            if (!Response.ReadBoolean()) throw new InvalidOperationException(Response.ReadString());
        }
        catch (Exception error) when (error is IOException or EndOfStreamException or OperationCanceledException or InvalidDataException)
        {
            var timedOut = error is OperationCanceledException;
            var exit = _process is { HasExited: true } ? $" It exited with code {_process.ExitCode}." : string.Empty;
            _connectionFailed = true;
            TerminateProcess();
            throw new InvalidOperationException(timedOut ? Pcsx2Exceptions.ProcessTimeout() : Pcsx2Exceptions.ProcessCommunicationFailed(exit), error);
        }
    }

    private Task<byte[]> ReadResponseAsync() =>
        EmulationHostProtocolFunctions.ReadResponseAsync(_pipe!, TimeSpan.FromSeconds(30),
            CancellationToken.None, length => Pcsx2Exceptions.InvalidResponseLength(length));

    private void TerminateProcess()
    {
        DisposeSafely(_pipe);
        _pipe = null;
        var process = _process;
        _process = null;
        if (process is null) return;
        try { WaitForProcessExit(process, graceful: false); }
        finally { DisposeSafely(process); }
    }

    private static void WaitForProcessExit(Process process, bool graceful)
    => EmulationChildProcessLifetime.WaitForExit(process, graceful, ProcessCoreConstants.GracefulShutdownTimeoutMilliseconds);

    private static void DisposeSafely(IDisposable? value)
    {
        try { value?.Dispose(); }
        catch (Exception) { }
    }

    private BinaryReader Response => _responseReader ?? throw new InvalidOperationException(Pcsx2Exceptions.HostResponseUnavailable());

}

