    private ExternalCoreApi.VoidCall? _deinitialize;
    private ExternalCoreApi.VoidCall? _unloadGame;
    private ExternalCoreApi.VoidCall? _run;
    private ExternalCoreApi.VoidCall? _reset;
    private ExternalCoreApi.SetControllerPortDevice? _setControllerPortDevice;
    private ExternalCoreApi.GetSerializedSize? _getSerializedSize;
    private ExternalCoreApi.Serialize? _serialize;
    private ExternalCoreApi.Serialize? _unserialize;
    private MachineConfiguration? _configuration;
    private string? _sessionDirectory;
    private string? _saveDirectory;
    private bool _gameLoaded;
    private bool _initialized;
    private bool _disposing;
    private IReadOnlyList<CoreControllerPort>? _controllerPorts;
    private IReadOnlyList<(string Source, string Native, int Size)> _firmwareFiles = [];

    internal ExternalCore(CoreDefinition definition, string corePath)
    {
        _definition = definition;
        _corePath = corePath;
    }

    public VideoFrame? LatestVideoFrame => _host?.LatestVideoFrame;
    public AudioChunk? LatestAudioChunk => _host?.LatestAudioChunk;
    public IReadOnlyList<CoreOption> Options => _host?.OptionCatalog ?? [];
    public IReadOnlyList<string> Diagnostics => _host?.Diagnostics ?? [];
    public IReadOnlyDictionary<int, bool> LedStates => _host?.LedStates ?? new Dictionary<int, bool>();
    public bool ShutdownRequested => _host?.ShutdownRequested ?? false;
    public IReadOnlyList<ControllerFeedbackState> ControllerFeedback => (_host?.Feedback.Snapshot() ?? [])
        .Select(state => state with { Port = _controllerPorts?.FirstOrDefault(port => port.NativeDevice == ExternalHostCallbacksConstants.JoypadDevice && port.NativePort == state.Port)?.ConfigurationPort ?? state.Port }).ToArray();
    public string CoreName { get; private set; } = string.Empty;
    public string CoreVersion { get; private set; } = string.Empty;
    public IReadOnlySet<string> SupportedContentExtensions { get; private set; } =
        new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public string CoreSha256 { get; private set; } = string.Empty;
    public double FramesPerSecond => _host?.FramesPerSecond ?? ExternalCoreConstants.FallbackFramesPerSecond;
    public int SampleRate => _host?.SampleRate ?? ExternalCoreConstants.FallbackSampleRate;
    public int DiskCount => _host?.DiskControl.ImageCount ?? 0;
    public int CurrentDiskIndex => _host?.DiskControl.CurrentIndex ?? -1;

    public bool TryDequeueAudio(out AudioChunk? chunk)
    {
        if (_host is not null) return _host.TryDequeueAudio(out chunk);
        chunk = null;
        return false;
    }

    public void Initialize(MachineConfiguration configuration, string sessionDirectory, string? saveDirectory = null)
    {
        _configuration = configuration;
        _sessionDirectory = Path.GetFullPath(sessionDirectory);
        _saveDirectory = saveDirectory is null ? null : Path.GetFullPath(saveDirectory);
        _saveMemoryReady = false;
        var media = ResolveConfiguredMedia(configuration);
        var contentPlan = _definition.CreateContentLoadPlan?.Invoke(configuration);
        foreach (var item in media)
            if (!File.Exists(item.Path))
                throw new FileNotFoundException(CoreExceptions.MediaNotFound(), item.Path);

        var sourceCorePath = ResolveCorePath(_corePath);
        using (var stream = File.OpenRead(sourceCorePath))
            CoreSha256 = Convert.ToHexString(SHA256.HashData(stream));

        saveDirectory = Path.GetFullPath(saveDirectory ?? Path.Combine(sessionDirectory, CoreDirectoryConstants.SavesDirectoryName));
        var coreSaveDirectory = Path.Combine(saveDirectory, _definition.Id);
        var (systemDirectory, contentDirectory) = CoreDirectoryFunctions.NativeDataDirectories(_definition, sessionDirectory, saveDirectory);
        _saveMemoryRegions = (contentPlan?.SaveMemoryRegions ?? [new CoreSaveMemoryRegion(SaveMemoryConstants.SaveRamId, SaveMemoryConstants.FileName)])
            .Select(region => (region.Id, Path.Combine(coreSaveDirectory, region.FileName))).ToArray();
        Directory.CreateDirectory(systemDirectory);
        FirmwareConfigurationFunctions.CopySelectedFiles(configuration, new Engine().Adapter(configuration), systemDirectory);
        _definition.PrepareSystemFiles?.Invoke(configuration, systemDirectory);
        _firmwareFiles = _definition.FirmwarePersistence is { } persistence
            ? FirmwareRuntimeFunctions.Prepare(configuration, _definition.Id, persistence, systemDirectory, saveDirectory)
            : [];
        Directory.CreateDirectory(contentDirectory);
        Directory.CreateDirectory(saveDirectory);
        var isolatedCoreDirectory = Path.Combine(sessionDirectory, ExternalCoreConstants.CoreDirectory);
        Directory.CreateDirectory(isolatedCoreDirectory);
        var isolatedCorePath = Path.Combine(isolatedCoreDirectory, _definition.LibraryFileName);
        File.Copy(sourceCorePath, isolatedCorePath, true);
        var contentPath = PrepareContentPath(media, contentDirectory);
        var nativeSaveDirectory = PrepareMemoryCards(configuration, saveDirectory, systemDirectory);
        _controllerPorts = _definition.CreateControllerPorts?.Invoke(configuration);
        _host = new ExternalHostCallbacks(systemDirectory, contentDirectory, nativeSaveDirectory, configuration.Options ?? new Dictionary<string, string>(), _definition.StartupFailureDiagnostics, _controllerPorts);

        try
        {
            _library = new ExternalCoreLibrary(isolatedCorePath);
            var apiVersion = Export<ExternalCoreApi.GetApiVersion>(ExternalCoreConstants.RetroApiVersion)();
            if (apiVersion != ExternalCoreInteropConstants.ApiVersion)
                throw new NotSupportedException(CoreExceptions.UnsupportedApiVersion(apiVersion));
            Export<ExternalCoreApi.GetSystemInfo>(ExternalCoreConstants.RetroGetSystemInfo)(out var info);
            var libraryName = Marshal.PtrToStringUTF8(info.LibraryName);
            if (!CoreIdentityFunctions.Accepts(_definition, libraryName))
                throw new InvalidDataException(CoreExceptions.LibraryIdentityMismatch(libraryName));
            CoreName = libraryName!;
            CoreVersion = Marshal.PtrToStringUTF8(info.LibraryVersion) ?? string.Empty;
            SupportedContentExtensions = ExternalCoreLibrary.ParseExtensions(info.ValidExtensions);
            ValidateExtension(contentPath);
            foreach (var path in contentPlan?.Paths ?? []) ValidateExtension(path);

            Export<ExternalCoreApi.SetEnvironment>(ExternalCoreConstants.RetroSetEnvironment)(_host.Environment);
            Export<ExternalCoreApi.SetVideo>(ExternalCoreConstants.RetroSetVideoRefresh)(_host.Video);
            Export<ExternalCoreApi.SetAudioSample>(ExternalCoreConstants.RetroSetAudioSample)(_host.AudioSample);
            Export<ExternalCoreApi.SetAudioBatch>(ExternalCoreConstants.RetroSetAudioSampleBatch)(_host.AudioBatch);
            Export<ExternalCoreApi.SetInputPoll>(ExternalCoreConstants.RetroSetInputPoll)(_host.InputPoll);
            Export<ExternalCoreApi.SetInputState>(ExternalCoreConstants.RetroSetInputState)(_host.InputState);
            _deinitialize = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroDeinit);
            _unloadGame = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroUnloadGame);
            _run = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroRun);
            _reset = Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroReset);
            _getSerializedSize = Export<ExternalCoreApi.GetSerializedSize>(ExternalCoreConstants.RetroSerializeSize);
            _serialize = Export<ExternalCoreApi.Serialize>(ExternalCoreConstants.RetroSerialize);
            _unserialize = Export<ExternalCoreApi.Serialize>(ExternalCoreConstants.RetroUnserialize);
            _getMemoryData = Export<ExternalCoreApi.GetMemoryData>(ExternalCoreConstants.RetroGetMemoryData);
            _getMemorySize = Export<ExternalCoreApi.GetMemorySize>(ExternalCoreConstants.RetroGetMemorySize);
            Export<ExternalCoreApi.VoidCall>(ExternalCoreConstants.RetroInit)();
            _initialized = true;
            _host.ValidateConfiguredOptions();
            _setControllerPortDevice = Export<ExternalCoreApi.SetControllerPortDevice>(ExternalCoreConstants.RetroSetControllerPortDevice);
            ApplyConfiguredControllers(requireAdvertised: false);

            var loadGame = Export<ExternalCoreApi.LoadGame>(ExternalCoreConstants.RetroLoadGame);
            if (contentPlan is not null)
                _gameLoaded = LoadSubsystem(contentPlan, info.NeedFullPath);
            else if (contentPath is null)
            {
                if (!_host.SupportsNoGame)
                    throw new InvalidOperationException(CoreExceptions.StartWithoutMediaUnsupported());
                _gameLoaded = loadGame(0);
            }
            else _gameLoaded = LoadGame(loadGame, contentPath, info.NeedFullPath);
            _host.DiagnosticMonitor.ThrowIfFailed();
            if (!_gameLoaded) throw new InvalidOperationException(CoreExceptions.ContentRefused());
            _host.ValidateConfiguredOptions();
            ApplyConfiguredControllers(requireAdvertised: true);
            RestoreSaveMemory();
            _saveMemoryReady = true;
            Export<ExternalCoreApi.GetSystemAvInfo>(ExternalCoreConstants.RetroGetSystemAvInfo)(out var av);
            _host.ApplyInitialAvInfo(av);
            _host.HardwareRender.Reset();
            _host.DiagnosticMonitor.ThrowIfFailed();
        }
        catch (Exception error)
        {
            var startupError = CoreDiagnosticMonitor.WithNativeDiagnostics(error, _host?.Diagnostics ?? []);
            try { Dispose(); }
            catch (Exception cleanupError) { throw new AggregateException(startupError, cleanupError); }
            if (!ReferenceEquals(startupError, error)) throw startupError;
            throw;
        }
    }

    internal static IReadOnlyList<MediaConfiguration> ResolveConfiguredMedia(MachineConfiguration configuration) => (configuration.Media ?? []).Where(item => item.IsInserted).OrderBy(item => item.MountOrder).ToArray();

    internal static string? PrepareContentPath(IReadOnlyList<MediaConfiguration> media, string contentDirectory)
    {
        if (media.Count == 0) return null;
        return Path.GetFullPath(media[0].Path);
    }

    public void RunFrame()
    {
        (_run ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized()))();
        _host?.DiagnosticMonitor.ThrowIfFailed();
    }
    public void HardReset()
    {
        var configuration = _configuration ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized());
        var sessionDirectory = _sessionDirectory ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized());
        var saveDirectory = _saveDirectory;
        Dispose();
        Initialize(configuration, sessionDirectory, saveDirectory);
    }
    public void SoftReset() => (_reset ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized()))();
    public void SetInput(EmulationInputSnapshot snapshot)
    {
        if (_host is not null) _host.Input = snapshot;
    }
    public void SetControllerPortDevice(int port, ControllerType type)
    {
        var configuration = _configuration ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized());
        var host = _host ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized());
        var setter = _setControllerPortDevice ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized());
        SemanticControllerFunctions.Validate(configuration, port, type);
        var route = _controllerPorts?.Single(item => item.ConfigurationPort == port);
        if (_gameLoaded && route is { CanChangeWhileRunning: false } && SemanticControllerFunctions.Resolve(configuration, port) != type)
            throw new NotSupportedException();
        var nativePort = route?.NativePort ?? (uint)port;
        if (route is null || route.NativeDevice == ExternalHostCallbacksConstants.JoypadDevice)
        {
            var nativeId = ControllerPortFunctions.Resolve(type, checked((int)nativePort), host.ControllerPorts);
            setter(nativePort, nativeId);
            host.Feedback.ResetPort(checked((int)nativePort));
        }
        host.SetControllerType(port, type);
        _configuration = SemanticControllerFunctions.WithControllerType(configuration, port, type);
    }

    private void ApplyConfiguredControllers(bool requireAdvertised)
    {
        var configuration = _configuration ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized());
        for (var port = SemanticPortConstants.MinimumControllerPort;
            port < SemanticControllerFunctions.PortCount(configuration); port++)
        {
            var type = SemanticControllerFunctions.Resolve(configuration, port);
            if (!requireAdvertised && !_host!.ControllerPorts.Any()
                && type is not (ControllerType.Joystick or ControllerType.DanceMat or ControllerType.ArcadeStick or ControllerType.None))
                continue;
            SetControllerPortDevice(port, type);
        }
        if (configuration.EmulatorId == Emulators.Rpcs3.Constants.CoreConstants.Id)
            for (var port = SemanticControllerFunctions.PortCount(configuration); port < 7; port++)
            {
                _setControllerPortDevice!((uint)port, 0u);
                _host!.SetControllerType(port, ControllerType.None);
            }
    }
    public void InsertMedia(string path) => (_host ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized())).DiskControl.Insert(path);
    public void EjectMedia() => (_host ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized())).DiskControl.Eject();
    public void SelectDisk(int index) => (_host ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized())).DiskControl.Select(index);

    public byte[] SaveState()
    {
        var size = (_getSerializedSize ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized()))();
        if (size == ExternalCoreInteropConstants.EmptyNativeSize || size > SavedStateConstants.MaximumStateSize)
            throw new InvalidOperationException(CoreExceptions.InvalidStateSize(size));
        var state = new byte[(int)size];
        var buffer = Marshal.AllocHGlobal(state.Length);
        try
        {
            if (!_serialize!(buffer, size))
                throw new InvalidOperationException(CoreExceptions.StateSaveFailed());
            Marshal.Copy(buffer, state, BufferConstants.FirstBufferIndex, state.Length);
        }
        finally { Marshal.FreeHGlobal(buffer); }
        return state;
    }

    public void LoadState(ReadOnlySpan<byte> state)
    {
        if (state.IsEmpty) throw new ArgumentException(CoreExceptions.StateEmpty(), nameof(state));
        var bytes = state.ToArray();
        var buffer = Marshal.AllocHGlobal(bytes.Length);
        try
        {
            Marshal.Copy(bytes, BufferConstants.FirstBufferIndex, buffer, bytes.Length);
            if (!_unserialize!(buffer, (nuint)bytes.Length))
                throw new InvalidOperationException(CoreExceptions.StateRestoreFailed());
        }
        finally { Marshal.FreeHGlobal(buffer); }
    }

    public void SetOption(string key, string value) => (_host ?? throw new InvalidOperationException(CoreExceptions.CoreNotInitialized())).SetOption(key, value);

    public void Stop()
    {
        if (!_gameLoaded) return;
        _gameLoaded = false;
        try { PersistSaveMemory(); }
        finally
        {
            try
            {
                try { _host?.HardwareRender.NotifyDestroy(); }
                finally { _unloadGame?.Invoke(); }
            }
            finally
            {
                try { PersistMemoryCards(); }
                finally
                {
                    _saveMemoryReady = false;
                    _memoryCardFiles.Clear();
                }
            }
        }
    }

    private void ValidateExtension(string? path)
    {
        if (path is null) return;
        var extension = Path.GetExtension(path).TrimStart(MediaConstants.ExtensionPrefix);
        if (!SupportedContentExtensions.Contains(extension))
            throw new InvalidDataException(CoreExceptions.UnsupportedContentExtension(extension));
    }

    private bool LoadGame(ExternalCoreApi.LoadGame loadGame, string path, bool needFullPath)
    {
        var nativePath = AllocateContentPath(path);
        var game = Marshal.AllocHGlobal(Marshal.SizeOf<ExternalCoreApi.GameInfo>());
        try
        {
            var content = needFullPath ? null : File.ReadAllBytes(path);
            Marshal.StructureToPtr(new ExternalCoreApi.GameInfo
            {
                Path = nativePath.Pointer,
                Data = content is null ? nint.Zero : AllocateContent(content),
                Size = content is null ? ExternalCoreInteropConstants.EmptyNativeSize : (nuint)content.Length
            }, game, false);
            return loadGame(game);
        }
        finally { Marshal.FreeHGlobal(game); }
    }

    private T Export<T>(string name) where T : Delegate => (_library ?? throw new InvalidOperationException(CoreExceptions.CoreNotLoaded())).Resolve<T>(name);

    private static string ResolveCorePath(string path)
    {
        if (!Path.IsPathFullyQualified(path))
            throw new ArgumentException(CoreExceptions.CorePathNotAbsolute(), nameof(path));
        if (!File.Exists(path)) throw new FileNotFoundException(CoreExceptions.CoreNotFound(), path);
        return path;
    }

    public void Dispose()
    {
        if (_disposing) return;
        _disposing = true;
        try
        {
            var callbacks = _host;
            try { _host?.HardwareRender.NotifyDestroy(); }
            finally
            {

                try { Stop(); }
                finally
                {
                    try
                    {
                        if (_initialized) _deinitialize?.Invoke();
                    }
                    finally
                    {
                        _initialized = false;
                        _deinitialize = null;
                        _unloadGame = null;
                        _run = null;
                        _reset = null;
                        _setControllerPortDevice = null;
                        _getSerializedSize = null;
                        _serialize = null;
                        _unserialize = null;
                        _getMemoryData = null;
                        _getMemorySize = null;
                        try { FirmwareRuntimeFunctions.Persist(_firmwareFiles); }
                        finally
                        {
                            _firmwareFiles = [];
                            try { _host?.Dispose(); }
                            finally
                            {
                                _host = null;
                                try { _library?.Dispose(); }
                                finally
                                {
                                    GC.KeepAlive(callbacks);
                                    _library = null;
                                    ReleaseContentBuffers();
                                }
                            }
                        }
                    }
                }
            }

        }
        finally { _disposing = false; }
    }
}

using System.IO;
using System.Runtime.InteropServices;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Constants;
using GWGUI.Emulation.Sony.Emulators.Common.Interop.Exceptions;
using NativeMemoryCards = GWGUI.Emulation.Sony.Emulators.Common.Interop.Functions.MemoryCardFunctions;

namespace GWGUI.Emulation.Sony.Emulators.Common.Interop.Services;

internal sealed partial class ExternalCore
{
    private ExternalCoreApi.GetMemoryData? _getMemoryData;
    private ExternalCoreApi.GetMemorySize? _getMemorySize;
    private IReadOnlyList<(uint Id, string Path)> _saveMemoryRegions = [];
    private bool _saveMemoryReady;
    private readonly List<(string Source, string Native)> _memoryCardFiles = [];

    private string PrepareMemoryCards(MachineConfiguration configuration, string saveDirectory, string systemDirectory)
    {
        _memoryCardFiles.Clear();
        if (configuration.Model == ModelConstants.PlayStation2)
        {
            NativeMemoryCards.PreparePs2(configuration, systemDirectory, _memoryCardFiles);
            return saveDirectory;
        }
        if (configuration.Model != ModelConstants.PlayStation) return saveDirectory;
        var directory = Path.Combine(_sessionDirectory!, MemoryCardConstants.Directory);
        Directory.CreateDirectory(directory);
        var names = NativeMemoryCards.NativeFileNames(configuration);
        for (var index = 0; index < names.Count; index++)
        {
            var source = NativeMemoryCards.SelectedPath(configuration, index);
            if (string.IsNullOrWhiteSpace(source)) continue;
            if (new FileInfo(source).Length != StorageSettingsFunctionsConstants.MemoryCardSize)
                throw new InvalidDataException(source);
            var destination = Path.Combine(directory, names[index]);
            File.Copy(source, destination, true);
            _memoryCardFiles.Add((source, destination));
        }
        return directory;
    }

    private void PersistMemoryCards()
    {
        if (!_saveMemoryReady) return;
        NativeMemoryCards.PersistFiles(_memoryCardFiles, _configuration?.Model == ModelConstants.PlayStation2 ? StorageSettingsFunctionsConstants.Ps2MemoryCardSize : StorageSettingsFunctionsConstants.MemoryCardSize);
    }

    private (nint Pointer, int Size) SaveMemory(uint id)
    {
        var size = _getMemorySize?.Invoke(id) ?? ExternalCoreInteropConstants.EmptyNativeSize;
        if (size == ExternalCoreInteropConstants.EmptyNativeSize) return default;
        if (size > SaveMemoryConstants.MaximumManagedBufferSize)
            throw new InvalidOperationException(CoreExceptions.InvalidStateSize(size));
        var pointer = _getMemoryData?.Invoke(id) ?? nint.Zero;
        return pointer == nint.Zero ? default : (pointer, checked((int)size));
    }

    private void RestoreSaveMemory()
    {
        if (_configuration?.Model == ModelConstants.PlayStation) return;
        foreach (var region in _saveMemoryRegions)
        {
            if (!File.Exists(region.Path)) continue;
            var memory = SaveMemory(region.Id);
            if (memory.Pointer == nint.Zero) continue;
            var bytes = File.ReadAllBytes(region.Path);
            if (bytes.Length != memory.Size)
                throw new InvalidDataException(CoreExceptions.InvalidStateSize((nuint)bytes.Length));
            Marshal.Copy(bytes, BufferConstants.FirstBufferIndex, memory.Pointer, bytes.Length);
        }
    }

    private void PersistSaveMemory()
    {
        if (_configuration?.Model == ModelConstants.PlayStation) return;
        if (!_saveMemoryReady) return;
        var errors = new List<Exception>();
        foreach (var region in _saveMemoryRegions)
            try { PersistSaveMemory(region.Id, region.Path); }
            catch (Exception error) { errors.Add(error); }
        if (errors.Count > 0) throw new AggregateException(errors);
    }

    private void PersistSaveMemory(uint id, string path)
    {
        var memory = SaveMemory(id);
        if (memory.Pointer == nint.Zero) return;
        var bytes = new byte[memory.Size];
        Marshal.Copy(memory.Pointer, bytes, BufferConstants.FirstBufferIndex, bytes.Length);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var temporaryPath = path + SaveMemoryConstants.TemporaryFileSuffix;
        try
        {
            File.WriteAllBytes(temporaryPath, bytes);
            File.Move(temporaryPath, path, overwrite: true);
        }
        finally
        {
            if (File.Exists(temporaryPath)) File.Delete(temporaryPath);
        }
    }
}

using System.IO;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Constants;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Enums;

namespace GWGUI.Emulation.Sony.Emulators.Pcsx2.Functions;

internal static class FileSystemFunctions
{
    private static bool Enabled(MachineConfiguration configuration, string option) => configuration.Options?.GetValueOrDefault(option) == EmulationSettingConstants.Enabled;

    private static string? PathSelection(MachineConfiguration configuration, string pathKey) => configuration.Options?.GetValueOrDefault(pathKey) is { } path && !string.IsNullOrWhiteSpace(path) ? path : null;

    private static string? Selection(MachineConfiguration configuration, string option, string pathKey) => Enabled(configuration, option)
        && (option != OptionConstants.UseExternalGameindexKey || GameIndexAvailable(configuration)) ? PathSelection(configuration, pathKey) : null;

    private static bool GameIndexAvailable(MachineConfiguration configuration)
    {
        var renderer = configuration.Options?.GetValueOrDefault(OptionConstants.RendererKey) ?? OptionValueFunctions.ToNative(RendererBackend.Automatic);
        return Enabled(configuration, OptionConstants.EnableHwHacksKey)
            && new[] { RendererBackend.Automatic, RendererBackend.OpenGl, RendererBackend.Direct3D11, RendererBackend.Direct3D12, RendererBackend.Vulkan }
                .Any(value => OptionValueFunctions.ToNative(value) == renderer);
    }

    internal static void Validate(MachineConfiguration configuration)
    {
        var gameIndex = Selection(configuration, OptionConstants.UseExternalGameindexKey, FileSystemConstants.GameIndexPathKey);
        if (gameIndex is not null && !File.Exists(gameIndex)) throw new FileNotFoundException(null, gameIndex);
        var cheats = Selection(configuration, OptionConstants.EnableCheatsKey, FileSystemConstants.CheatsDirectoryKey);
        if (cheats is not null && !Directory.Exists(cheats)) throw new DirectoryNotFoundException(cheats);
    }

    internal static string SystemDirectory(MachineConfiguration configuration, string physicalDirectory) => HardDiskRuntimeFunctions.Selected(configuration) is not null
        || Selection(configuration, OptionConstants.UseExternalGameindexKey, FileSystemConstants.GameIndexPathKey) is not null
        || PathSelection(configuration, FileSystemConstants.CheatsDirectoryKey) is not null ? FileSystemConstants.SystemUri : physicalDirectory;

    internal static (string Path, bool IsReadOnly) Resolve(MachineConfiguration configuration, string systemDirectory, string path, bool? cheatsEnabled = null)
    {
        var normalized = path.Replace('\\', '/');
        if (!normalized.Equals(FileSystemConstants.SystemUri, StringComparison.Ordinal)
            && !normalized.StartsWith(FileSystemConstants.SystemUri + "/", StringComparison.Ordinal)) return (path, false);
        var relative = normalized[FileSystemConstants.SystemUri.Length..].TrimStart('/');
        if (relative.Equals(HardDiskConstants.NativeFile, StringComparison.OrdinalIgnoreCase) && HardDiskRuntimeFunctions.Selected(configuration) is { } disk)
            return (Path.GetFullPath(disk.Path), disk.IsReadOnly);
        if (relative.Equals(FileSystemConstants.GameIndexFile, StringComparison.OrdinalIgnoreCase)
            && Selection(configuration, OptionConstants.UseExternalGameindexKey, FileSystemConstants.GameIndexPathKey) is { } database)
            return (Path.GetFullPath(database), true);
        if ((relative.Equals(FileSystemConstants.CheatsDirectory, StringComparison.OrdinalIgnoreCase)
            || relative.StartsWith(FileSystemConstants.CheatsDirectory + "/", StringComparison.OrdinalIgnoreCase))
            && (cheatsEnabled ?? Enabled(configuration, OptionConstants.EnableCheatsKey))
            && PathSelection(configuration, FileSystemConstants.CheatsDirectoryKey) is { } cheats)
            return (Within(cheats, relative[FileSystemConstants.CheatsDirectory.Length..].TrimStart('/')), true);
        return (Within(systemDirectory, relative), false);
    }

    private static string Within(string directory, string relative)
    {
        var root = Path.GetFullPath(directory);
        var resolved = Path.GetFullPath(Path.Combine(root, relative));
        if (!resolved.Equals(root, StringComparison.OrdinalIgnoreCase) && !resolved.StartsWith(root.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
            throw new InvalidDataException(relative);
        return resolved;
    }

    internal static IReadOnlyList<EmulationSettingsBlock> Describe(MachineConfiguration configuration, IReadOnlyList<EmulationSettingsBlock> blocks) => blocks
        .Select(block => block with { Fields = block.Fields.SelectMany(field => WithPath(configuration, field)).ToArray() }).ToArray();

    private static IEnumerable<EmulationSettingsField> WithPath(MachineConfiguration configuration, EmulationSettingsField field)
    {
        var database = field.Id == OptionConstants.UseExternalGameindexKey;
        var cheats = field.Id == OptionConstants.EnableCheatsKey;
        var available = !database || GameIndexAvailable(configuration);
        yield return database || cheats ? field with { RefreshSettingsOnChange = true, IsEnabled = field.IsEnabled && available }
            : field.Id is OptionConstants.EnableHwHacksKey or OptionConstants.RendererKey ? field with { RefreshSettingsOnChange = true } : field;
        if (!field.IsVisible || !database && !cheats) yield break;
        var key = database ? FileSystemConstants.GameIndexPathKey : FileSystemConstants.CheatsDirectoryKey;
        yield return new EmulationSettingsField(key, field.Tab, field.BlockId,
            database ? FileSystemConstants.GameIndexLabel : FileSystemConstants.CheatsDirectoryLabel,
            database ? EmulationSettingsEditor.Path : EmulationSettingsEditor.OpenDirectory,
            configuration.Options?.GetValueOrDefault(key), IsEnabled: cheats || available && field.Value == field.EnabledValue, RequiresRestart: true,
            DefaultFolderCategory: cheats ? EmulationDefaultFolderCategory.Cheats : null);
    }
}

using System.Globalization;
using System.IO;
using GWGUI.Emulation.Sony.Emulators.Pcsx2.Constants;

namespace GWGUI.Emulation.Sony.Emulators.Pcsx2.Functions;

internal static class HardDiskRuntimeFunctions
{
    internal static string NativeCapacity(int capacityGiB) => capacityGiB.ToString(CultureInfo.InvariantCulture) + " GiB";

    internal static MediaConfiguration? Selected(MachineConfiguration configuration)
    {
        var disks = (configuration.Media ?? []).Where(media => media.Category == MediaCategory.HardDisk && media.IsInserted).ToArray();
        if (disks.Length > 1) throw new InvalidDataException(nameof(configuration.Media));
        return disks.SingleOrDefault();
    }

    internal static MachineConfiguration Configure(MachineConfiguration configuration)
    {
        var disk = Selected(configuration);
        var options = new Dictionary<string, string>(configuration.Options ?? new Dictionary<string, string>(), StringComparer.Ordinal)
        {
            [OptionConstants.Dev9HddKey] = disk is null ? "disabled" : "enabled",
            [OptionConstants.Dev9HddSizeKey] = NativeCapacity(HardDiskConstants.DefaultCapacityGiB)
        };
        if (disk is not null)
        {
            var size = new FileInfo(disk.Path).Length;
            // ATA IDENTIFY advertises the configured capacity, independently of the
            // file length. Do not round a different image size to a native preset.
            var capacity = size / HardDiskConstants.Gibibyte;
            if (size % HardDiskConstants.Gibibyte != 0 || capacity > HardDiskConstants.CapacitiesGiB.Max()
                || !HardDiskConstants.CapacitiesGiB.Contains((int)capacity))
                throw new InvalidDataException(disk.Path);
            options[OptionConstants.Dev9HddSizeKey] = NativeCapacity((int)capacity);
        }
        return configuration with { Options = options };
    }

}

using System.IO;
using System.IO.Compression;
using GWGUI.Emulation.Sony.Emulators.Ppsspp.Constants;
using GWGUI.Emulation.Sony.Emulators.Ppsspp.Exceptions;

namespace GWGUI.Emulation.Sony.Emulators.Ppsspp.Functions;

internal static class SystemFilesFunctions
{
    internal static bool IsInstalled(string directory) => SystemFilesConstants.RequiredFiles.All(file => File.Exists(Path.Combine(directory, SystemFilesConstants.DirectoryName, file)));

    internal static void Validate(string directory)
    {
        foreach (var file in SystemFilesConstants.RequiredFiles)
        {
            var path = Path.Combine(directory, SystemFilesConstants.DirectoryName, file);
            if (!File.Exists(path)) throw new FileNotFoundException(PpssppExceptions.SystemFilesMissing(), path);
        }
    }

    internal static async Task InstallAsync(HttpClient client, string directory, CancellationToken cancellationToken)
    {
        var root = Path.GetFullPath(directory);
        var staging = Path.Combine(root, SystemFilesConstants.StagingPrefix + Guid.NewGuid().ToString("N"));
        var previous = staging + SystemFilesConstants.PreviousSuffix;
        var installed = Path.Combine(root, SystemFilesConstants.DirectoryName);
        var replaced = false;
        Directory.CreateDirectory(staging);
        try
        {
            using var response = await client.GetAsync(SystemFilesConstants.PackageUrl, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();
            await using (var source = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false))
            using (var package = new MemoryStream())
            {
                await source.CopyToAsync(package, cancellationToken).ConfigureAwait(false);
                package.Position = 0;
                using var archive = new ZipArchive(package, ZipArchiveMode.Read);
                archive.ExtractToDirectory(staging);
            }
            Validate(staging);
            cancellationToken.ThrowIfCancellationRequested();
            if (Directory.Exists(installed)) Directory.Move(installed, previous);
            try
            {
                Directory.Move(Path.Combine(staging, SystemFilesConstants.DirectoryName), installed);
                replaced = true;
            }
            catch
            {
                if (Directory.Exists(previous)) Directory.Move(previous, installed);
                throw;
            }
        }
        finally
        {
            try { if (Directory.Exists(staging)) Directory.Delete(staging, true); }
            finally { if (replaced && Directory.Exists(previous)) Directory.Delete(previous, true); }
        }
    }
}

