internal static class PcFxBackupMemoryFunctions
{
    internal static void ValidateExternalCard(string path)
    {
        if (!File.Exists(path) || new FileInfo(path).Length != PcFxBackupMemoryConstants.BankSize)
            throw new InvalidDataException(BeetlePcfxExceptions.InvalidBackupSize(path));
    }

    internal static void EnsureInternalFile(string directory)
    {
        Directory.CreateDirectory(directory);
        var path = Path.Combine(directory, PcFxBackupMemoryConstants.InternalFileName);
        if (File.Exists(path)) return;
        using var backup = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None);
        backup.SetLength(PcFxBackupMemoryConstants.BankSize);
    }

    internal static void Load(ExternalCoreApi.GetMemoryData getData, ExternalCoreApi.GetMemorySize getSize, string directory, string? externalPath)
    {
        var memory = Memory(getData, getSize);
        LoadBank(Path.Combine(directory, PcFxBackupMemoryConstants.InternalFileName), memory);
        if (!string.IsNullOrWhiteSpace(externalPath))
            LoadBank(externalPath, memory + PcFxBackupMemoryConstants.BankSize);
    }

    internal static void Save(ExternalCoreApi.GetMemoryData getData, ExternalCoreApi.GetMemorySize getSize, string directory, string? externalPath)
    {
        var memory = Memory(getData, getSize);
        SaveBank(Path.Combine(directory, PcFxBackupMemoryConstants.InternalFileName), memory);
        if (!string.IsNullOrWhiteSpace(externalPath))
            SaveBank(externalPath, memory + PcFxBackupMemoryConstants.BankSize);
    }

    private static nint Memory(ExternalCoreApi.GetMemoryData getData, ExternalCoreApi.GetMemorySize getSize)
    {
        var size = getSize(PcFxBackupMemoryConstants.SaveRamType);
        var memory = getData(PcFxBackupMemoryConstants.SaveRamType);
        if (memory == IntPtr.Zero || size != PcFxBackupMemoryConstants.BankCount
            * PcFxBackupMemoryConstants.BankSize)
            throw new InvalidDataException(BeetlePcfxExceptions.UnexpectedBackupMemorySize());
        return memory;
    }

    private static void LoadBank(string path, nint memory)
    {
        if (!File.Exists(path)) return;
        var bytes = File.ReadAllBytes(path);
        if (bytes.Length != PcFxBackupMemoryConstants.BankSize)
            throw new InvalidDataException(BeetlePcfxExceptions.InvalidBackupSize(path));
        if (bytes.All(value => value == PcFxBackupMemoryConstants.EmptyFileByte)) return;
        Marshal.Copy(bytes, PcFxBackupMemoryConstants.FirstByteOffset, memory, bytes.Length);
    }

    private static void SaveBank(string path, nint memory)
    {
        var bytes = new byte[PcFxBackupMemoryConstants.BankSize];
        Marshal.Copy(memory, bytes, PcFxBackupMemoryConstants.FirstByteOffset, bytes.Length);
        var directory = Path.GetDirectoryName(path);
        if (directory is not null) Directory.CreateDirectory(directory);
        var temporary = path + PcFxBackupMemoryConstants.TemporaryNameSeparator + Guid.NewGuid().ToString(PcFxBackupMemoryConstants.TemporaryIdFormat) + PcFxBackupMemoryConstants.TemporarySuffix;
        try
        {
            File.WriteAllBytes(temporary, bytes);
            File.Move(temporary, path, true);
        }
        finally
        {
            if (File.Exists(temporary)) File.Delete(temporary);
        }
    }
}

using GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Exceptions;
using GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Constants;
using GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Factories;
using GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Functions;
using GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Services;
using GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Enums;

using System.IO.Pipes;
using System.Runtime.Versioning;
using System.Text.Json;

using System.IO;

namespace GWGUI.Emulation.Nec.Emulators.BeetlePcfx.Services;

public static class CoreHost
                {
    [SupportedOSPlatform(CoreHostConstants.Windows)]
    public static void Run(string pipeName, string videoMapName)
    {
        EmulationHostProtocolFunctions.WithSharedVideoMap(videoMapName, 0, videoMap =>
            EmulationHostProtocolFunctions.RunConnectedSession(pipeName, CoreHostConstants.Value, 15_000, (reader, transportWriter) =>
            {
                ExternalCore? core = null;
                var lastVideoSequence = 0L;
                var lastDiagnosticCount = 0;
                try
                {
                    EmulationHostProtocolFunctions.RunCommandLoop<HostCommand>(reader, transportWriter, static commandReader => (HostCommand)commandReader.ReadByte(), HostCommand.Dispose, (command, writer) =>
                    {
                        switch (command)
                        {
                            case HostCommand.Initialize:
                                var (corePath, session, saves, configuration) =
                                    EmulationHostProtocolFunctions.ReadInitializationRequest(reader,
                                        CoreHostProtocol.ReadString,
                                        static requestReader => JsonSerializer.Deserialize<MachineConfiguration>(requestReader.ReadString(), CoreHostProtocol.JsonOptions) ?? throw new InvalidDataException(BeetlePcfxExceptions.HostConfigurationInvalid()));
                                EmulationHostProtocolFunctions.DisposePreviousCore(ref core);
                                core = new ExternalCore(corePath);
                                core.Initialize(configuration, session, saves);
                                writer.Write(true);
                                EmulationHostProtocolFunctions.WriteCoreInitialization<ExternalCore, MachineConfiguration, CoreOption>(
                                    writer, core, CoreHostProtocol.JsonOptions, ref lastDiagnosticCount, '|');
                                EmulationHostProtocolFunctions.WriteDiskSelection(writer, core);
                                CoreHostProtocol.WriteLedStates(writer, core.LedStates);
                                break;
                            case HostCommand.RunFrame:
                                var activeCore = EnsureCore(core);
                                EmulationHostProtocolFunctions.RunCoreFrame<ExternalCore, MachineConfiguration, CoreOption>(
                                    reader, writer, activeCore, CoreHostProtocol.ReadInput,
                                    (frameWriter, pendingFrame) => CoreHostProtocol.WriteSharedFrame(frameWriter, pendingFrame, videoMap),
                                    EmulationHostProtocolFunctions.WriteDiskSelection, CoreHostProtocol.WriteLedStates, static () => CoreHostProtocol.JsonOptions,
                                    ref lastVideoSequence, ref lastDiagnosticCount);
                                break;
                            case HostCommand.SoftReset:
                                EnsureCore(core).SoftReset();
                                WriteSuccess(writer);
                                break;
                            case HostCommand.Dispose:
                                EmulationHostProtocolFunctions.DisposePreviousCore(ref core);
                                WriteSuccess(writer);
                                break;
                            default:
                                if (!EmulationHostProtocolFunctions.TryExecutePathMediaCommand((byte)command, reader, writer,
                                        () => EnsureCore(core), CoreHostProtocol.ReadBytes, WriteSuccess))
                                    throw new InvalidDataException(BeetlePcfxExceptions.UnknownHostCommand((byte)command));
                                break;
                        }
                    }, (writer, error) =>
                    {
                        writer.Write(false);
                        writer.Write((byte)(error is GWGUI.Emulation.Nec.Common.Exceptions.CoreMediaRequiredException ? GWGUI.Emulation.Nec.Common.Enums.CoreHostErrorKind.MediaRequired : GWGUI.Emulation.Nec.Common.Enums.CoreHostErrorKind.General));
                        writer.Write(error.ToString());
                    });
                }
                finally
                {
                    EmulationHostProtocolFunctions.DisposePreviousCore(ref core);
                }
            }));
    }

    private static ExternalCore EnsureCore(ExternalCore? core) => core ?? throw new InvalidOperationException(BeetlePcfxExceptions.HostNotInitialized());
    private static void WriteSuccess(BinaryWriter writer) => writer.Write(true);
}

