        if (device == AnalogDevice)
            return (index, id) switch
            {
                (0, 0) => controller.LeftX,
                (0, 1) => controller.LeftY,
                (1, 0) => controller.RightX,
                (1, 1) => controller.RightY,
                _ => 0
            };
        return 0;
    }

    private static short Bool(bool value) => value ? (short)1 : (short)0;
    private static short ClampToShort(int value) => (short)Math.Clamp(value, short.MinValue, short.MaxValue);
    private static int AccumulatePointerCoordinate(int coordinate, int delta) => (int)Math.Clamp((long)coordinate + (long)delta * PointerCoordinateScale, PointerCoordinateMinimum, PointerCoordinateMaximum);
    private static int SaturatingAdd(int left, int right) => (int)Math.Clamp((long)left + right, int.MinValue, int.MaxValue);

    private static IReadOnlyDictionary<uint, EmulationKey> CreateKeyboardMap()
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.CreateKeyMap().Where(pair => pair.Key is not (EmulationKey.LeftAmiga or EmulationKey.RightAmiga or EmulationKey.Break or EmulationKey.Undo)).ToDictionary(pair => pair.Value, pair => pair.Key);

}

using GWGUI.Emulation.Nintendo.Emulators.Common.Interop.Exceptions;
using GWGUI.Emulation.Nintendo.Emulators.Common.Interop.Constants;
using GWGUI.Emulation.Nintendo.Emulators.Common.Interop.Contracts;
using GWGUI.Emulation.Nintendo.Emulators.Common.Interop.Functions;
using GWGUI.Emulation.Nintendo.Emulators.Common.Interop.Services;

using System.IO;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Collections.Concurrent;
using GWGUI.Emulation;

namespace GWGUI.Emulation.Nintendo.Emulators.Common.Interop.Services;

internal sealed partial class ExternalHostCallbacks : IDisposable
{
    private static readonly IReadOnlyDictionary<uint, EmulationKey> KeyboardMap = CreateKeyboardMap();
    private readonly Dictionary<string, string> _options = new(StringComparer.Ordinal);
    private readonly HashSet<string> _configuredOptionKeys = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ExternalCoreUtf8String> _nativeStrings = new(StringComparer.Ordinal);
    private readonly Stopwatch _clock = Stopwatch.StartNew();
    private EmulationPixelFormat _pixelFormat = EmulationPixelFormat.Rgb565;
    private float _aspectRatio;
    private long _videoSequence;
    private long _audioSequence;
    private bool _disposed;
    private int _optionsUpdated;
    private readonly object _inputGate = new();
    private EmulationInputSnapshot _pendingInput = EmulationInputSnapshot.Empty;
    private EmulationInputSnapshot _polledInput = EmulationInputSnapshot.Empty;
    private int _pointerX = ExternalHostCallbacksConstants.PointerCoordinateCenter;
    private int _pointerY = ExternalHostCallbacksConstants.PointerCoordinateCenter;
    private IReadOnlySet<EmulationKey> _previousKeys = new HashSet<EmulationKey>();
    private ExternalCoreApi.KeyboardEvent? _keyboardEvent;
    private ExternalCoreApi.UpdateCoreOptionsDisplay? _updateOptionsDisplay;
    private bool _suppressFullscreenChord;
    private readonly Dictionary<string, bool> _optionVisibility = new(StringComparer.Ordinal);
    internal ExternalDiskControl DiskControl { get; } = new();

    internal ExternalHostCallbacks(string systemDirectory, string contentDirectory, string saveDirectory, IReadOnlyDictionary<string, string>? options)
    {
        Directory.CreateDirectory(systemDirectory);
        Directory.CreateDirectory(contentDirectory);
        Directory.CreateDirectory(saveDirectory);
        SystemDirectory = Path.GetFullPath(systemDirectory);
        ContentDirectory = Path.GetFullPath(contentDirectory);
        SaveDirectory = Path.GetFullPath(saveDirectory);
        if (options is not null)
            foreach (var option in options)
            {
                _options[option.Key] = option.Value;
                _configuredOptionKeys.Add(option.Key);
            }

        Environment = HandleEnvironment;
        Video = HandleVideo;
        AudioSample = HandleAudioSample;
        AudioBatch = HandleAudioBatch;
        InputPoll = HandleInputPoll;
        InputState = HandleInputState;
        Log = HandleLog;
        Led = HandleLed;
    }

    internal string SystemDirectory { get; }
    internal string ContentDirectory { get; }
    internal string SaveDirectory { get; }
    internal VideoFrame? LatestVideoFrame { get; private set; }
    internal AudioChunk? LatestAudioChunk { get; private set; }
    private readonly GWGUI.Emulation.Services.EmulationAudioBuffer _audioBuffer = new();
    private readonly ConcurrentQueue<string> _diagnostics = new();
    private readonly ConcurrentDictionary<int, bool> _ledStates = new();
    private readonly ConcurrentDictionary<int, long> _ledActivityUntil = new();
    private readonly HashSet<uint> _unknownEnvironmentCommands = [];
    internal EmulationInputSnapshot Input
    {
        set
        {
            lock (_inputGate)
            {
                var pointer = value.Pointer with
                {
                    DeltaX = SaturatingAdd(_pendingInput.Pointer.DeltaX, value.Pointer.DeltaX),
                    DeltaY = SaturatingAdd(_pendingInput.Pointer.DeltaY, value.Pointer.DeltaY),
                    Wheel = SaturatingAdd(_pendingInput.Pointer.Wheel, value.Pointer.Wheel)
                };
                _pendingInput = value with { Pointer = pointer };
            }
        }
    }
    internal ExternalCoreApi.EnvironmentCallback Environment { get; }
    internal ExternalCoreApi.VideoCallback Video { get; }
    internal ExternalCoreApi.AudioSampleCallback AudioSample { get; }
    internal ExternalCoreApi.AudioBatchCallback AudioBatch { get; }
    internal ExternalCoreApi.InputPollCallback InputPoll { get; }
    internal ExternalCoreApi.InputStateCallback InputState { get; }
    internal ExternalCoreApi.LogCallback Log { get; }
    internal ExternalCoreApi.SetLedState Led { get; }
    internal int SampleRate { get; set; } = 44100;
    internal double FramesPerSecond { get; private set; } = 50;
    internal bool SupportsNoGame { get; private set; }
    internal IReadOnlyList<IReadOnlyList<ControllerDevice>> ControllerPorts { get; private set; } = [];
    internal IReadOnlyList<CoreOption> OptionCatalog { get; private set; } = [];
    internal IReadOnlyList<string> Diagnostics => _diagnostics.ToArray();
    internal IReadOnlyDictionary<int, bool> LedStates
    {
        get
        {
            var now = Stopwatch.GetTimestamp();
            return _ledStates.Keys.Concat(_ledActivityUntil.Keys).Distinct().ToDictionary(key => key, key => _ledStates.GetValueOrDefault(key) || _ledActivityUntil.GetValueOrDefault(key) > now);
        }
    }
    internal int BufferedAudioFrames => _audioBuffer.BufferedFrames;
    internal long AudioOverrunCount => _audioBuffer.NativeOverrunCount;

    internal void SetOption(string key, string value)
    {
        if (!OptionCatalog.Any(option => option.Key.Equals(key, StringComparison.Ordinal)))
            throw new ArgumentOutOfRangeException(nameof(key), key, CoreExceptions.UnknownCoreOption());
        var option = OptionCatalog.First(item => item.Key.Equals(key, StringComparison.Ordinal));
        if (option.Values.Count > 0 && !option.Values.Any(item => item.Value.Equals(value, StringComparison.Ordinal)))
            throw new ArgumentOutOfRangeException(nameof(value), value, CoreExceptions.InvalidOptionValue(value, key));
        _options[key] = value;
        Interlocked.Exchange(ref _optionsUpdated, 1);
        _updateOptionsDisplay?.Invoke();
    }

    public void Dispose()
    {
        if (_disposed) return;
        try
        {
            try { DestroyHardwareContext(); }
            finally
            {
            foreach (var pointer in _nativeStrings.Values)
            {
                try { pointer.Dispose(); }
                catch (Exception) { }
            }
            }
        }
        finally
        {
            ReleaseExtendedGameInfo();
            _contentPathOverrides.Clear();
            _nativeStrings.Clear();
            _keyboardEvent = null;
            _updateOptionsDisplay = null;
            LatestVideoFrame = null;
            _audioBuffer.ClearNative(() => LatestAudioChunk = null);
            lock (_inputGate)
            {
                _pendingInput = EmulationInputSnapshot.Empty;
                _polledInput = EmulationInputSnapshot.Empty;
                _previousKeys = new HashSet<EmulationKey>();
            }
            _disposed = true;
        }
    }
}

using System.Diagnostics;
using System.Runtime.InteropServices;
using GWGUI.Emulation;
using static GWGUI.Emulation.Commodore.Emulators.Common.Interop.Constants.ExternalHostCallbacksConstants;

namespace GWGUI.Emulation.Commodore.Emulators.Common.Interop.Services;

internal sealed partial class ExternalHostCallbacks
{
    private void HandleInputPoll()
    {
        lock (_inputGate)
        {
            _polledInput = _pendingInput with { Keys = GWGUI.Emulation.Commodore.Common.Machines.Common.Functions.KeyboardBindingFunctions.Expand(_pendingInput.Keys, _keyboardExpansions, _keyboardToggleExpansions, _activeKeyboardToggles, _previousKeyboardToggleSources) };
            _pendingInput = _pendingInput with
            {
                Pointer = _pendingInput.Pointer with { DeltaX = InputSnapshotFunctionsConstants.NoPointerMovement, DeltaY = InputSnapshotFunctionsConstants.NoPointerMovement, Wheel = InputSnapshotFunctionsConstants.NoWheelMovement, HorizontalWheel = InputSnapshotFunctionsConstants.NoWheelMovement }
            };
        }
        PublishKeyboardTransitions(_polledInput.Keys);
    }

    internal static IReadOnlySet<EmulationKey> ExpandKeyboardKeys(IReadOnlySet<EmulationKey> keys, IReadOnlyDictionary<EmulationKey, IReadOnlyList<EmulationKey>> expansions)
    {
        var expanded = new HashSet<EmulationKey>(keys.Where(key => !expansions.ContainsKey(key)));
        foreach (var key in keys)
            if (expansions.TryGetValue(key, out var chord)) expanded.UnionWith(chord);
        return expanded;
    }

    private void PublishKeyboardTransitions(IReadOnlySet<EmulationKey> keys)
    {
        if (_keyboardEvent is null) return;
        var reverseMap = _keyboardMap.ToDictionary(pair => pair.Value, pair => pair.Key);
        ExternalCoreKeyboardFunctions.PublishTransitions(keys, reverseMap,
            ExternalCoreKeyboardFunctions.Modifiers(keys), ref _previousKeys, ref _keyboardEvent,
            IsModifier, CharacterFor);
    }

    private static uint CharacterFor(uint code, IReadOnlySet<EmulationKey> keys)
    {
        var shifted = keys.Contains(EmulationKey.LeftShift) || keys.Contains(EmulationKey.RightShift);
        var caps = keys.Contains(EmulationKey.CapsLock);
        if (code is >= (uint)NativeKeyboardKey.FirstLetter and <= (uint)NativeKeyboardKey.LastLetter) return shifted ^ caps ? code - AsciiCaseOffset : code;
        if (!shifted) return code is >= FirstPrintableCharacter and <= LastPrintableCharacter ? code : NoCharacter;
        return code switch
        {
            (uint)CharacterDigitZero => CharacterRightParenthesis, (uint)CharacterDigitOne => CharacterExclamationMark, (uint)CharacterDigitTwo => CharacterAtSign, (uint)CharacterDigitThree => CharacterNumberSign, (uint)CharacterDigitFour => CharacterDollarSign,
            (uint)CharacterDigitFive => CharacterPercent, (uint)CharacterDigitSix => CharacterCaret, (uint)CharacterDigitSeven => CharacterAmpersand, (uint)CharacterDigitEight => CharacterAsterisk, (uint)CharacterDigitNine => CharacterLeftParenthesis,
            (uint)CharacterMinus => CharacterUnderscore, (uint)CharacterEquals => CharacterPlus, (uint)CharacterLeftBracket => CharacterLeftBrace, (uint)CharacterRightBracket => CharacterRightBrace, (uint)CharacterBackslash => CharacterVerticalBar,
            (uint)CharacterSemicolon => CharacterColon, (uint)CharacterQuote => CharacterDoubleQuote, (uint)CharacterComma => CharacterLessThan, (uint)CharacterPeriod => CharacterGreaterThan, (uint)CharacterSlash => CharacterQuestionMark,
            (uint)CharacterBackquote => CharacterTilde, _ => code is >= FirstPrintableCharacter and <= LastPrintableCharacter ? code : NoCharacter
        };
    }

    private static bool IsModifier(EmulationKey key) => key is EmulationKey.LeftShift or EmulationKey.RightShift
        or EmulationKey.LeftControl or EmulationKey.RightControl or EmulationKey.LeftAlt or EmulationKey.RightAlt
        or EmulationKey.LeftAmiga or EmulationKey.RightAmiga or EmulationKey.CommodoreKey or EmulationKey.CommodoreShiftLock;

    private void HandleLog(int level, nint format)
    {
        var message = format == nint.Zero ? null : Marshal.PtrToStringUTF8(format);
        if (!string.IsNullOrWhiteSpace(message)) AddDiagnostic(string.Format(LogMessageFormat, level, message.TrimEnd()));
    }

    private void HandleLed(int led, int state)
    {
        if (led is not (>= FirstLedIndex and < MaximumLedCount)) return;
        _ledStates[led] = state != ExternalCoreInteropConstants.InactiveState;
        if (state != ExternalCoreInteropConstants.InactiveState)
            _ledActivityUntil[led] = Stopwatch.GetTimestamp() + Stopwatch.Frequency * LedActivityMilliseconds / MillisecondsPerSecond;
    }

    private void AddDiagnostic(string message)
    {
        _diagnostics.Enqueue(message);
        while (_diagnostics.Count > MaximumDiagnosticCount) _diagnostics.TryDequeue(out _);
    }

    private short HandleInputState(uint port, uint device, uint index, uint id)
    {
        var input = _polledInput;
        if (device == KeyboardDevice)
            return _keyboardMap.TryGetValue(id, out var key) && input.Keys.Contains(key) ? PressedInput : ReleasedInput;

        if (device == MouseDevice && port == ControllerPortConstants.MinimumControllerPort)
            return id switch
            {
                (uint)NativeMouseInput.DeltaX => ClampToShort(input.Pointer.DeltaX),
                (uint)NativeMouseInput.DeltaY => ClampToShort(input.Pointer.DeltaY),
                (uint)NativeMouseInput.LeftButton => Bool(input.Pointer.Left),
                (uint)NativeMouseInput.RightButton => Bool(input.Pointer.Right),
                (uint)NativeMouseInput.WheelUp => Bool(input.Pointer.Wheel > InputSnapshotFunctionsConstants.NoWheelMovement),
                (uint)NativeMouseInput.WheelDown => Bool(input.Pointer.Wheel < InputSnapshotFunctionsConstants.NoWheelMovement),
                (uint)NativeMouseInput.MiddleButton => Bool(input.Pointer.Middle),
                _ => ReleasedInput
            };

        if (port >= input.Controllers.Count) return ReleasedInput;
        var controller = input.Controllers[(int)port];
        if (device == JoypadDevice)
        {
            if (id == JoypadMask) return unchecked((short)(controller.Buttons & ushort.MaxValue));
            return id < ControllerButtonBitCount && (controller.Buttons & (InputSnapshotFunctionsConstants.SingleButtonMask << (int)id)) != InputSnapshotFunctionsConstants.NoPressedButtons ? PressedInput : ReleasedInput;
        }
        if (device == AnalogDevice)
            return (index, id) switch
            {
                ((uint)NativeAnalogStick.Left, (uint)NativeAnalogAxis.X) => controller.LeftX,
                ((uint)NativeAnalogStick.Left, (uint)NativeAnalogAxis.Y) => controller.LeftY,
                ((uint)NativeAnalogStick.Right, (uint)NativeAnalogAxis.X) => controller.RightX,
                ((uint)NativeAnalogStick.Right, (uint)NativeAnalogAxis.Y) => controller.RightY,
                _ => ReleasedInput
            };
        return ReleasedInput;
    }

    private static short Bool(bool value) => value ? PressedInput : ReleasedInput;
    private static short ClampToShort(int value) => (short)Math.Clamp(value, short.MinValue, short.MaxValue);
    private static int SaturatingAdd(int left, int right) => (int)Math.Clamp((long)left + right, int.MinValue, int.MaxValue);

    private static IReadOnlyDictionary<uint, EmulationKey> CreateKeyboardMap(IReadOnlyDictionary<uint, EmulationKey?>? overrides)
    {
        var map = new Dictionary<uint, EmulationKey>
        {
            [(uint)NativeKeyboardKey.Backspace] = EmulationKey.Backspace, [(uint)NativeKeyboardKey.Tab] = EmulationKey.Tab, [(uint)NativeKeyboardKey.Return] = EmulationKey.Return,
            [(uint)NativeKeyboardKey.Escape] = EmulationKey.Escape, [(uint)NativeKeyboardKey.Space] = EmulationKey.Space, [(uint)NativeKeyboardKey.Comma] = EmulationKey.Comma,
            [(uint)NativeKeyboardKey.Minus] = EmulationKey.Minus, [(uint)NativeKeyboardKey.Period] = EmulationKey.Period, [(uint)NativeKeyboardKey.Slash] = EmulationKey.Slash,
            [(uint)NativeKeyboardKey.Semicolon] = EmulationKey.Semicolon, [(uint)NativeKeyboardKey.Equals] = EmulationKey.Equals, [(uint)NativeKeyboardKey.LeftBracket] = EmulationKey.LeftBracket,
            [(uint)NativeKeyboardKey.Backslash] = EmulationKey.Backslash, [(uint)NativeKeyboardKey.RightBracket] = EmulationKey.RightBracket, [(uint)NativeKeyboardKey.Quote] = EmulationKey.Quote,
            [(uint)NativeKeyboardKey.Backquote] = EmulationKey.Backquote, [(uint)NativeKeyboardKey.Delete] = EmulationKey.Delete,
            [(uint)NativeKeyboardKey.Up] = EmulationKey.Up, [(uint)NativeKeyboardKey.Down] = EmulationKey.Down, [(uint)NativeKeyboardKey.Right] = EmulationKey.Right,
            [(uint)NativeKeyboardKey.Left] = EmulationKey.Left, [(uint)NativeKeyboardKey.Insert] = EmulationKey.Insert, [(uint)NativeKeyboardKey.Home] = EmulationKey.Home,
            [(uint)NativeKeyboardKey.End] = EmulationKey.End, [(uint)NativeKeyboardKey.PageUp] = EmulationKey.PageUp, [(uint)NativeKeyboardKey.PageDown] = EmulationKey.PageDown,
            [(uint)NativeKeyboardKey.CapsLock] = EmulationKey.CapsLock, [(uint)NativeKeyboardKey.RightShift] = EmulationKey.RightShift, [(uint)NativeKeyboardKey.LeftShift] = EmulationKey.LeftShift,
            [(uint)NativeKeyboardKey.RightControl] = EmulationKey.RightControl, [(uint)NativeKeyboardKey.LeftControl] = EmulationKey.LeftControl,
            [(uint)NativeKeyboardKey.RightAlt] = EmulationKey.RightAlt, [(uint)NativeKeyboardKey.LeftAlt] = EmulationKey.LeftAlt,
            [(uint)NativeKeyboardKey.LeftAmiga] = EmulationKey.LeftAmiga, [(uint)NativeKeyboardKey.RightAmiga] = EmulationKey.RightAmiga, [(uint)NativeKeyboardKey.Help] = EmulationKey.Help
        };
        for (var index = BufferConstants.FirstCollectionIndex; index < AlphabetLetterCount; index++) map[(uint)((uint)NativeKeyboardKey.FirstLetter + index)] = (EmulationKey)((int)EmulationKey.A + index);
        for (var index = BufferConstants.FirstCollectionIndex; index < DecimalDigitCount; index++) map[(uint)(CharacterDigitZero + index)] = (EmulationKey)((int)EmulationKey.D0 + index);
        for (var index = BufferConstants.FirstCollectionIndex; index < FunctionKeyCount; index++) map[(uint)((uint)NativeKeyboardKey.FirstFunctionKey + index)] = (EmulationKey)((int)EmulationKey.F1 + index);
        for (var index = BufferConstants.FirstCollectionIndex; index < DecimalDigitCount; index++) map[(uint)((uint)NativeKeyboardKey.FirstNumpadDigit + index)] = (EmulationKey)((int)EmulationKey.Numpad0 + index);
        map[(uint)NativeKeyboardKey.NumpadPeriod] = EmulationKey.NumpadPeriod; map[(uint)NativeKeyboardKey.NumpadDivide] = EmulationKey.NumpadDivide;
        map[(uint)NativeKeyboardKey.NumpadMultiply] = EmulationKey.NumpadMultiply; map[(uint)NativeKeyboardKey.NumpadMinus] = EmulationKey.NumpadMinus;
        map[(uint)NativeKeyboardKey.NumpadPlus] = EmulationKey.NumpadPlus; map[(uint)NativeKeyboardKey.NumpadEnter] = EmulationKey.NumpadEnter;
        if (overrides is not null)
            foreach (var item in overrides)
            {
                if (item.Value is not { } target) { map.Remove(item.Key); continue; }
                foreach (var alias in map.Where(pair => pair.Value == target).Select(pair => pair.Key).ToArray()) map.Remove(alias);
                map[item.Key] = target;
            }
        return map;
    }

}

using System.IO;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Collections.Concurrent;
using GWGUI.Emulation;

namespace GWGUI.Emulation.Commodore.Emulators.Common.Interop.Services;
internal sealed partial class ExternalHostCallbacks : IDisposable
{
    private readonly IReadOnlyDictionary<uint, EmulationKey> _keyboardMap;
    private readonly IReadOnlyDictionary<EmulationKey, IReadOnlyList<EmulationKey>> _keyboardExpansions;
    private readonly IReadOnlyDictionary<EmulationKey, IReadOnlyList<EmulationKey>> _keyboardToggleExpansions;
    private readonly HashSet<EmulationKey> _activeKeyboardToggles = new();
    private readonly HashSet<EmulationKey> _previousKeyboardToggleSources = new();
    private readonly string? _pathOption;
    private readonly Dictionary<string, string> _options = new(StringComparer.Ordinal);
    private readonly HashSet<string> _configuredOptionKeys = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ExternalCoreUtf8String> _nativeStrings = new(StringComparer.Ordinal);
    private readonly Stopwatch _clock = Stopwatch.StartNew();
    private EmulationPixelFormat _pixelFormat = EmulationPixelFormat.Rgb565;
    private float _aspectRatio;
    private long _videoSequence;
    private long _audioSequence;
    private bool _disposed;
    private int _optionsUpdated;
    private readonly object _inputGate = new();
    private EmulationInputSnapshot _pendingInput = EmulationInputSnapshot.Empty;
    private EmulationInputSnapshot _polledInput = EmulationInputSnapshot.Empty;
    private IReadOnlySet<EmulationKey> _previousKeys = new HashSet<EmulationKey>();
    private ExternalCoreApi.KeyboardEvent? _keyboardEvent;
    private ExternalCoreApi.UpdateCoreOptionsDisplay? _updateOptionsDisplay;
    private readonly Dictionary<string, bool> _optionVisibility = new(StringComparer.Ordinal);
    internal ExternalDiskControl DiskControl { get; } = new();

    internal ExternalHostCallbacks(
        string systemDirectory,
        string contentDirectory,
        string saveDirectory,
        IReadOnlyDictionary<string, string>? options,
        string? pathOption = null,
        IReadOnlyDictionary<uint, EmulationKey?>? keyboardOverrides = null,
        IReadOnlyDictionary<EmulationKey, IReadOnlyList<EmulationKey>>? keyboardExpansions = null,
        IReadOnlyDictionary<EmulationKey, IReadOnlyList<EmulationKey>>? keyboardToggleExpansions = null
    )
    {
        _keyboardMap = CreateKeyboardMap(keyboardOverrides);
        _keyboardExpansions = keyboardExpansions ?? new Dictionary<EmulationKey, IReadOnlyList<EmulationKey>>();
        _keyboardToggleExpansions = keyboardToggleExpansions ?? new Dictionary<EmulationKey, IReadOnlyList<EmulationKey>>();
        _pathOption = pathOption;
        Directory.CreateDirectory(systemDirectory);
        Directory.CreateDirectory(contentDirectory);
        Directory.CreateDirectory(saveDirectory);
        SystemDirectory = Path.GetFullPath(systemDirectory);
        ContentDirectory = Path.GetFullPath(contentDirectory);
        SaveDirectory = Path.GetFullPath(saveDirectory);
        if (options is not null)
            foreach (var option in options)
            {
                _options[option.Key] = option.Value;
                _configuredOptionKeys.Add(option.Key);
            }

        Environment = HandleEnvironment;
        Video = HandleVideo;
        AudioSample = HandleAudioSample;
        AudioBatch = HandleAudioBatch;
        InputPoll = HandleInputPoll;
        InputState = HandleInputState;
        Log = HandleLog;
        Led = HandleLed;
    }

    internal string SystemDirectory { get; }
    internal string ContentDirectory { get; }
    internal string SaveDirectory { get; }
    internal VideoFrame? LatestVideoFrame { get; private set; }
    internal AudioChunk? LatestAudioChunk { get; private set; }
    private readonly GWGUI.Emulation.Services.EmulationAudioBuffer _audioBuffer = new();
    private readonly ConcurrentQueue<string> _diagnostics = new();
    private readonly ConcurrentDictionary<int, bool> _ledStates = new();
    private readonly ConcurrentDictionary<int, long> _ledActivityUntil = new();
    private readonly HashSet<uint> _unknownEnvironmentCommands = [];
    internal EmulationInputSnapshot Input
    {
        set
        {
            lock (_inputGate)
            {
                var pointer = value.Pointer with
                {
                    DeltaX = SaturatingAdd(_pendingInput.Pointer.DeltaX, value.Pointer.DeltaX),
                    DeltaY = SaturatingAdd(_pendingInput.Pointer.DeltaY, value.Pointer.DeltaY),
                    Wheel = SaturatingAdd(_pendingInput.Pointer.Wheel, value.Pointer.Wheel)
                };
                _pendingInput = value with
                {
                    Pointer = pointer
                };
            }
        }
    }

    internal ExternalCoreApi.EnvironmentCallback Environment { get; }
    internal ExternalCoreApi.VideoCallback Video { get; }
    internal ExternalCoreApi.AudioSampleCallback AudioSample { get; }
    internal ExternalCoreApi.AudioBatchCallback AudioBatch { get; }
    internal ExternalCoreApi.InputPollCallback InputPoll { get; }
    internal ExternalCoreApi.InputStateCallback InputState { get; }
    internal ExternalCoreApi.LogCallback Log { get; }
    internal ExternalCoreApi.SetLedState Led { get; }
    internal int SampleRate { get; set; } = ExternalHostCallbacksConstants.DefaultSampleRate;
    internal double FramesPerSecond { get; private set; } = ExternalHostCallbacksConstants.DefaultFrameRate;
    internal bool SupportsNoGame { get; private set; }
    internal IReadOnlyList<IReadOnlyList<ControllerDevice>> ControllerPorts { get; private set; } = [];
    internal IReadOnlyList<CoreOption> OptionCatalog { get; private set; } = [];
    internal IReadOnlyList<string> Diagnostics => _diagnostics.ToArray();

    internal IReadOnlyDictionary<int, bool> LedStates
    {
        get
        {
            var now = Stopwatch.GetTimestamp();
            return _ledStates.Keys.Concat(_ledActivityUntil.Keys).Distinct().ToDictionary(key => key, key => _ledStates.GetValueOrDefault(key) || _ledActivityUntil.GetValueOrDefault(key) > now);
        }
    }

    internal int BufferedAudioFrames => _audioBuffer.BufferedFrames;

    internal long AudioOverrunCount => _audioBuffer.NativeOverrunCount;

    internal void SetOption(string key, string value)
    {
        if (!OptionCatalog.Any(option => option.Key.Equals(key, StringComparison.Ordinal)))
            throw new ArgumentOutOfRangeException(nameof(key), key, CoreExceptions.UnknownCoreOption());
        var option = OptionCatalog.First(item => item.Key.Equals(key, StringComparison.Ordinal));
        if (option.Values.Count > BufferConstants.EmptyCollectionCount && !option.Values.Any(item => item.Value.Equals(value, StringComparison.Ordinal)))
            throw new ArgumentOutOfRangeException(nameof(value), value, CoreExceptions.InvalidOptionValue(value, key));
        _options[key] = value;
        Interlocked.Exchange(ref _optionsUpdated, ExternalHostCallbacksConstants.OptionsChangedState);
        _updateOptionsDisplay?.Invoke();
    }

    public void Dispose()
    {
        if (_disposed) return;
        Exception? failure = null;
        try
        {
            foreach (var text in _nativeStrings.Values)
            {
                try { text.Dispose(); }
                catch (Exception error) { failure ??= error; }
            }
        }
        finally
        {
            _nativeStrings.Clear();
            lock (_inputGate)
            {
                _activeKeyboardToggles.Clear();
                _previousKeyboardToggleSources.Clear();
                _previousKeys = new HashSet<EmulationKey>();
            }
            _disposed = true;
        }
        if (failure is not null) System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();
    }
}

