using System.Collections.Concurrent;
using GWGUI.Emulation;

namespace GWGUI.Emulation.Amstrad.Emulators.Common.Interop.Services;

internal sealed partial class ExternalHostCallbacks : IDisposable
{
    private readonly IReadOnlyDictionary<uint, EmulationKey> _keyboardMap;
    private readonly Dictionary<string, string> _options = new(StringComparer.Ordinal);
    private readonly HashSet<string> _configuredOptionKeys = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ExternalCoreUtf8String> _nativeStrings = new(StringComparer.Ordinal);
    private readonly Stopwatch _clock = Stopwatch.StartNew();
    private EmulationPixelFormat _pixelFormat = EmulationPixelFormat.Rgb565;
    private float _aspectRatio;
    private long _videoSequence;
    private long _audioSequence;
    private bool _disposed;
    private int _optionsUpdated;
    private readonly object _inputGate = new();
    private EmulationInputSnapshot _pendingInput = EmulationInputSnapshot.Empty;
    private EmulationInputSnapshot _polledInput = EmulationInputSnapshot.Empty;
    private int _pointerX = ExternalHostCallbacksConstants.PointerCoordinateCenter;
    private int _pointerY = ExternalHostCallbacksConstants.PointerCoordinateCenter;
    private IReadOnlySet<EmulationKey> _previousKeys = new HashSet<EmulationKey>();
    private ExternalCoreApi.KeyboardEvent? _keyboardEvent;
    private ExternalCoreApi.UpdateCoreOptionsDisplay? _updateOptionsDisplay;
    private bool _suppressFullscreenChord;
    private readonly Dictionary<string, bool> _optionVisibility = new(StringComparer.Ordinal);
    internal ExternalDiskControl DiskControl { get; } = new();

    internal ExternalHostCallbacks(string systemDirectory, string contentDirectory,
        string saveDirectory, IReadOnlyDictionary<string, string>? options, bool createDirectories = true, IReadOnlyDictionary<uint, EmulationKey?>? keyboardOverrides = null)
    {
        _keyboardMap = CreateKeyboardMap(keyboardOverrides);
        if (createDirectories)
        {
            Directory.CreateDirectory(systemDirectory);
            Directory.CreateDirectory(contentDirectory);
            Directory.CreateDirectory(saveDirectory);
        }
        SystemDirectory = Path.GetFullPath(systemDirectory);
        ContentDirectory = Path.GetFullPath(contentDirectory);
        SaveDirectory = Path.GetFullPath(saveDirectory);
        if (options is not null)
            foreach (var option in options)
            {
                _options[option.Key] = option.Value;
                _configuredOptionKeys.Add(option.Key);
            }

        Environment = HandleEnvironment;
        Video = HandleVideo;
        AudioSample = HandleAudioSample;
        AudioBatch = HandleAudioBatch;
        InputPoll = HandleInputPoll;
        InputState = HandleInputState;
        Log = HandleLog;
        Led = HandleLed;
    }

    internal string SystemDirectory { get; }
    internal string ContentDirectory { get; }
    internal string SaveDirectory { get; }
    internal VideoFrame? LatestVideoFrame { get; private set; }
    internal AudioChunk? LatestAudioChunk { get; private set; }
    private readonly GWGUI.Emulation.Services.EmulationAudioBuffer _audioBuffer = new();
    private readonly ConcurrentQueue<string> _diagnostics = new();
    private readonly ConcurrentDictionary<int, bool> _ledStates = new();
    private readonly ConcurrentDictionary<int, long> _ledActivityUntil = new();
    private readonly HashSet<uint> _unknownEnvironmentCommands = [];
    internal EmulationInputSnapshot Input
    {
        set
        {
            lock (_inputGate)
            {
                var pointer = value.Pointer with
                {
                    DeltaX = EmulationInputMappingFunctions.SaturatingAdd(_pendingInput.Pointer.DeltaX, value.Pointer.DeltaX),
                    DeltaY = EmulationInputMappingFunctions.SaturatingAdd(_pendingInput.Pointer.DeltaY, value.Pointer.DeltaY),
                    Wheel = EmulationInputMappingFunctions.SaturatingAdd(_pendingInput.Pointer.Wheel, value.Pointer.Wheel)
                };
                _pendingInput = value with { Pointer = pointer };
            }
        }
    }
    internal ExternalCoreApi.EnvironmentCallback Environment { get; }
    internal ExternalCoreApi.VideoCallback Video { get; }
    internal ExternalCoreApi.AudioSampleCallback AudioSample { get; }
    internal ExternalCoreApi.AudioBatchCallback AudioBatch { get; }
    internal ExternalCoreApi.InputPollCallback InputPoll { get; }
    internal ExternalCoreApi.InputStateCallback InputState { get; }
    internal ExternalCoreApi.LogCallback Log { get; }
    internal ExternalCoreApi.SetLedState Led { get; }
    internal int SampleRate { get; set; } = AudioConstants.DefaultSampleRate;
    internal double FramesPerSecond { get; private set; } = VideoConstants.DefaultFramesPerSecond;
    internal bool SupportsNoGame { get; private set; }
    internal IReadOnlyList<IReadOnlyList<ControllerDevice>> ControllerPorts { get; private set; } = [];
    internal IReadOnlyList<CoreOption> OptionCatalog { get; private set; } = [];
    internal IReadOnlyList<string> Diagnostics => _diagnostics.ToArray();
    internal IReadOnlyDictionary<int, bool> LedStates
    {
        get
        {
            var now = Stopwatch.GetTimestamp();
            return _ledStates.Keys.Concat(_ledActivityUntil.Keys).Distinct().ToDictionary(key => key, key => _ledStates.GetValueOrDefault(key) || _ledActivityUntil.GetValueOrDefault(key) > now);
        }
    }
    internal int BufferedAudioFrames => _audioBuffer.BufferedFrames;
    internal long AudioOverrunCount => _audioBuffer.NativeOverrunCount;

    internal void SetOption(string key, string value)
    {
        if (!OptionCatalog.Any(option => option.Key.Equals(key, StringComparison.Ordinal)))
            throw new ArgumentOutOfRangeException(nameof(key), key, CommonExceptions.UnknownCoreOption());
        var option = OptionCatalog.First(item => item.Key.Equals(key, StringComparison.Ordinal));
        if (option.Values.Count > BufferConstants.EmptyCollectionCount && !option.Values.Any(item => item.Value.Equals(value, StringComparison.Ordinal)))
            throw new ArgumentOutOfRangeException(nameof(value), value, CommonExceptions.InvalidOptionValue(value, key));
        _options[key] = value;
        Interlocked.Exchange(ref _optionsUpdated, ExternalCoreInteropConstants.OptionsUpdatedState);
        _updateOptionsDisplay?.Invoke();
    }

    public void Dispose()
    {
        if (_disposed) return;
        try
        {
            foreach (var pointer in _nativeStrings.Values)
            {
                try { pointer.Dispose(); }
                catch (Exception) { }
            }
        }
        finally
        {
            _nativeStrings.Clear();
            _keyboardEvent = null;
            _updateOptionsDisplay = null;
            LatestVideoFrame = null;
            _audioBuffer.ClearNative(() => LatestAudioChunk = null);
            lock (_inputGate)
            {
                _pendingInput = EmulationInputSnapshot.Empty;
                _polledInput = EmulationInputSnapshot.Empty;
                _previousKeys = new HashSet<EmulationKey>();
            }
            _disposed = true;
        }
    }
}

using GWGUI.Emulation.Nec.Emulators.Common.Interop.Constants;
using GWGUI.Emulation.Nec.Emulators.Common.Interop.Contracts;
using GWGUI.Emulation.Nec.Emulators.Common.Interop.Functions;
using GWGUI.Emulation.Nec.Emulators.Common.Interop.Services;

using System.Diagnostics;
using System.Runtime.InteropServices;
using GWGUI.Emulation;
using static GWGUI.Emulation.Nec.Emulators.Common.Interop.Constants.ExternalHostCallbacksConstants;

namespace GWGUI.Emulation.Nec.Emulators.Common.Interop.Services;

internal sealed partial class ExternalHostCallbacks
{
    internal static IReadOnlySet<EmulationKey> SupportedKeyboardKeys { get; } =
        KeyboardMap.Values.ToHashSet();

    private void HandleInputPoll()
    {
        lock (_inputGate)
        {
            _polledInput = _pendingInput;
            _pointerX = AccumulatePointerCoordinate(_pointerX, _polledInput.Pointer.DeltaX);
            _pointerY = AccumulatePointerCoordinate(_pointerY, _polledInput.Pointer.DeltaY);
            _pendingInput = _pendingInput with
            {
                Pointer = _pendingInput.Pointer with { DeltaX = 0, DeltaY = 0, Wheel = 0, HorizontalWheel = 0 }
            };
        }
        PublishKeyboardTransitions(_polledInput.Keys);
    }

    private void PublishKeyboardTransitions(IReadOnlySet<EmulationKey> keys)
    {
        if (_keyboardEvent is null) return;
        keys = FilterReservedKeyboardChord(keys);
        var reverseMap = KeyboardMap.ToDictionary(pair => pair.Value, pair => pair.Key);
        ExternalCoreKeyboardFunctions.PublishTransitions(keys, reverseMap,
            ExternalCoreKeyboardFunctions.Modifiers(keys), ref _previousKeys, ref _keyboardEvent,
            IsModifier, CharacterFor);
    }

    internal IReadOnlySet<EmulationKey> FilterReservedKeyboardChord(IReadOnlySet<EmulationKey> keys)
    {
        var alt = keys.Contains(EmulationKey.LeftAlt) || keys.Contains(EmulationKey.RightAlt);
        var enter = keys.Contains(EmulationKey.Return) || keys.Contains(EmulationKey.NumpadEnter);
        if (alt && enter) _suppressFullscreenChord = true;
        if (!_suppressFullscreenChord) return keys;
        if (!alt && !enter) _suppressFullscreenChord = false;
        return keys.Where(key => key is not (EmulationKey.LeftAlt or EmulationKey.RightAlt or EmulationKey.Return or EmulationKey.NumpadEnter)).ToHashSet();
    }

    private static uint CharacterFor(uint code, IReadOnlySet<EmulationKey> keys)
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.Character(code, keys);

    private static bool IsModifier(EmulationKey key) => key is EmulationKey.LeftShift or EmulationKey.RightShift or EmulationKey.LeftControl or EmulationKey.RightControl or EmulationKey.LeftAlt or EmulationKey.RightAlt;

    private void HandleLog(int level, nint format)
    {
        var message = format == 0 ? null : Marshal.PtrToStringUTF8(format);
        if (!string.IsNullOrWhiteSpace(message)) AddDiagnostic($"[{level}] {message.TrimEnd()}");
    }

    private void HandleLed(int led, int state)
    {
        if (led is not (>= 0 and < 256)) return;
        _ledStates[led] = state != 0;
        if (state != 0)
            _ledActivityUntil[led] = Stopwatch.GetTimestamp() + Stopwatch.Frequency * 140 / 1000;
    }

    private void AddDiagnostic(string message)
    {
        _diagnostics.Enqueue(message);
        while (_diagnostics.Count > 500) _diagnostics.TryDequeue(out _);
    }

    private short HandleInputState(uint port, uint device, uint index, uint id)
    {
        var input = _polledInput;
        if (device == KeyboardDevice)
            return KeyboardMap.TryGetValue(id, out var key) && input.Keys.Contains(key) ? (short)1 : (short)0;

        if (device == MouseDevice)
            return id switch
            {
                0 => ClampToShort(input.Pointer.DeltaX),
                1 => ClampToShort(input.Pointer.DeltaY),
                2 => Bool(input.Pointer.Left),
                3 => Bool(input.Pointer.Right),
                4 => Bool(input.Pointer.Wheel > 0),
                5 => Bool(input.Pointer.Wheel < 0),
                6 => Bool(input.Pointer.Middle),
                _ => 0
            };

        if (device == PointerDevice && port == 0)
            return id switch
            {
                PointerX => (short)_pointerX,
                PointerY => (short)_pointerY,
                PointerPressed => Bool(input.Pointer.Left),
                _ => 0
            };

        if (port >= input.Controllers.Count) return 0;
        var controller = input.Controllers[(int)port];
        if (device == JoypadDevice)
        {
            var buttons = controller.Buttons;
            if (id == JoypadMask) return unchecked((short)(buttons & ushort.MaxValue));
            return id < 32 && (buttons & (1u << (int)id)) != 0 ? (short)1 : (short)0;
        }
        if (device == AnalogDevice)
            return (index, id) switch
            {
                (0, 0) => controller.LeftX,
                (0, 1) => controller.LeftY,
                (1, 0) => controller.RightX,
                (1, 1) => controller.RightY,
                _ => 0
            };
        return 0;
    }

    private static short Bool(bool value) => value ? (short)1 : (short)0;
    private static short ClampToShort(int value) => (short)Math.Clamp(value, short.MinValue, short.MaxValue);
    private static int AccumulatePointerCoordinate(int coordinate, int delta) => (int)Math.Clamp((long)coordinate + (long)delta * PointerCoordinateScale, PointerCoordinateMinimum, PointerCoordinateMaximum);

    private static IReadOnlyDictionary<uint, EmulationKey> CreateKeyboardMap()
    => GWGUI.Emulation.Functions.ExternalCoreKeyboardFunctions.CreateKeyMap().Where(pair => pair.Key is not (EmulationKey.LeftAmiga or EmulationKey.RightAmiga or EmulationKey.Break or EmulationKey.Undo)).ToDictionary(pair => pair.Value, pair => pair.Key);

}

